// ============================================================================
// CPU Reference Converters (Bit-exact match with shaders/arg_converter.hlsl)
// ============================================================================
void ConvertClasFromTrianglesCPU(
    const NvTrianglesToClasArgs& src,
    D3D12_RTAS_OPERATION_BUILD_CLAS_FROM_TRIANGLES_ARGS& dst)
{
    std::memset(&dst, 0, sizeof(dst));
    dst.ClusterID                    = src.clusterId;
    dst.ClusterFlags                 = src.clusterFlags;
    dst.TriangleCount                = static_cast<uint16_t>((src.packedCounts >> 0) & 0x1FFu);
    dst.UniqueVertexIndexCount       = static_cast<uint16_t>((src.packedCounts >> 9) & 0x1FFu);
    dst.BaseGeometryIndexAndFlags    = src.baseGeometryIndexAndFlags;
    dst.OpacityMicromapBaseLocation  = 0;
    dst.VertexBufferStride           = src.vertexBufferStride;
    // Per-arg NvAPI index format -> explicit element stride (DXR side is declared UINT8; the
    // low byte of a 16/32-bit cluster-local index is the index). See shaders/arg_converter.hlsl.
    const uint32_t idxFmt            = (src.packedCounts >> 24) & 0xFu;
    dst.IndexBufferStride            = src.indexBufferStride != 0
        ? src.indexBufferStride
        : static_cast<uint16_t>((idxFmt == 2u || idxFmt == 4u) ? idxFmt : 1u);
    dst.OpacityMicromapIndexBufferStride   = src.opacityMicromapIndexBufferStride;
    dst.GeometryIndexAndFlagsArrayStride   = src.geometryIndexAndFlagsBufferStride;
    dst.PositionTruncateBitCount     = static_cast<uint16_t>((src.packedCounts >> 18) & 0x3Fu);
    dst.ReservedPadding              = 0;
    dst.VertexBuffer                 = src.vertexBuffer;
    dst.IndexBuffer                  = src.indexBuffer;
    dst.GeometryIndexAndFlagsArray   = src.geometryIndexAndFlagsBuffer;
    dst.GeometryIndexAndFlagsIndexBuffer = 0;
    dst.OpacityMicromapArray         = src.opacityMicromapArray;
    dst.OpacityMicromapIndexBuffer   = src.opacityMicromapIndexBuffer;
}

void ConvertTemplatesFromTrianglesCPU(
    const NvTrianglesToTemplateArgs& src,
    D3D12_RTAS_OPERATION_BUILD_CLUSTER_TEMPLATES_FROM_TRIANGLES_ARGS& dst)
{
    std::memset(&dst, 0, sizeof(dst));
    ConvertClasFromTrianglesCPU(src, dst.TrianglesArgs);
    dst.InstantiationBoundingBoxLimit       = src.instantiationBoundingBoxLimit;
    dst.Compressed1.Header.field0           = 0;
    dst.Compressed1.ReservedPadding         = 0;
}

void ConvertInstantiateTemplatesCPU(
    const NvInstantiateTemplateArgs& src,
    D3D12_RTAS_OPERATION_INSTANTIATE_CLUSTER_TEMPLATES_ARGS& dst)
{
    dst.GeometryIndexOffset          = static_cast<int32_t>(src.geometryIndexOffset);
    dst.ClusterIdOffset              = src.clusterIdOffset;
    dst.ClusterTemplate              = src.clusterTemplate;
    dst.VertexBuffer.StartAddress    = src.vertexBufferStartAddress;
    dst.VertexBuffer.StrideInBytes   = src.vertexBufferStrideInBytes;
}

void ConvertClasToBlasCPU(
    const NvClasToBlasArgs& src,
    D3D12_RTAS_OPERATION_BUILD_BLAS_FROM_CLAS_ARGS& dst)
{
    dst.ClasAddressCount  = src.clasCount;
    dst.ClasAddressStride = 8u; // NvAPI: "reserved, must be 0"; CLAS address arrays are 8-byte strided
    dst.ClasAddressArray  = src.clasAddresses;
}

void ConvertPtlasWriteInstanceCPU(
    const NvPtlasWriteInstanceArgs& src,
    D3D12_RTAS_PARTITIONED_TLAS_OPERATION_WRITE_INSTANCE_ARGS& dst)
{
    std::memset(&dst, 0, sizeof(dst));
    std::memcpy(dst.Transform, src.transform, sizeof(src.transform));
    dst.InstanceID                          = src.instanceID;
    dst.InstanceMask                        = src.instanceMask;
    dst.InstanceContributionToHitGroupIndex = src.instanceContributionToHitGroupIndex;
    dst.InstanceFlags                       = src.instanceFlags;
    dst.AccelerationStructure               = src.accelerationStructure;
    dst.InstanceIndex                       = src.instanceIndex;
    dst.PartitionIndex                      = src.partitionIndex;
    std::memcpy(&dst.ExplicitAABB, src.explicitAABB, sizeof(src.explicitAABB));
}

// ============================================================================
// GPU Compute Converter Pipeline & Scratch Allocator
// ============================================================================
namespace {

// ----------------------------------------------------------------------------
// Scratch pool
//
// Converted argument arrays and 64-bit result-size arrays live in wrapper-owned scratch
// buffers that the GPU reads/writes while the game's command list executes. A slot may only be
// reused (or released/grown) once the GPU is done with it. We have no fence on the game's
// queue, so each slot gets a 32-bit marker in a READBACK buffer: after the slot's last use the
// command list records WriteBufferImmediate(MARKER_OUT) of a fresh sequence value, and the CPU
// treats the slot as free once it reads that value back. Command lists that are never
// executed simply keep their slots reserved (bounded by kMaxScratchSlots).
// ----------------------------------------------------------------------------
constexpr uint32_t kMaxScratchSlots      = 1024;
constexpr uint64_t kMinScratchSize       = 64ull * 1024ull;
constexpr uint64_t kTimedReleaseMs       = 2000; // only when WriteBufferImmediate is unavailable
constexpr D3D12_RESOURCE_STATES kScratchCanonicalState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;

struct ScratchSlot {
    ComPtr<ID3D12Resource> buffer;
    uint64_t size          = 0;
    uint32_t pendingMarker = 0; // value the GPU writes once the slot's last use completed
    uint64_t releaseAfter  = 0; // GetTickCount64() deadline (fallback path only)
    bool     busy          = false;
};

struct DeviceConverterContext {
    ComPtr<ID3D12RootSignature> rootSig;
    ComPtr<ID3D12PipelineState> pso;
    ComPtr<ID3D12Resource>      markerBuffer;   // READBACK, one uint32 per slot
    volatile uint32_t*          markers = nullptr;
    std::vector<ScratchSlot>    slots;
    uint32_t                    nextMarker = 0;
    bool                        wbiDirect  = false;
    bool                        wbiCompute = false;
    bool                        warnedAddressFlags = false;
    bool                        warnedPoolFull     = false;
    bool                        warnedDstSanitize  = false;
    ComPtr<ID3D12Resource>      nullDstSink;    // receives results whose destination address is null

    // AMD_MG_DUMP_ARGS=1 diagnostics: raw copies of the game's argument / destination arrays.
    ComPtr<ID3D12Resource>      dumpGpu;        // DEFAULT, UAV
    ComPtr<ID3D12Resource>      dumpRb;         // READBACK, persistently mapped
    const uint8_t*              dumpMapped = nullptr;
    struct PendingDump {
        uint32_t slot, type, mode, argStride, dstStride, argCount, hasCount, seq;
        uint64_t argVa, dstVa, countVa;
    };
    std::vector<PendingDump>    pendingDumps;
    uint32_t                    dumpsPerType[8] = {};
    uint32_t                    dumpSeq   = 0;
    bool                        dumpTried = false;

    // Layout capture: complete argument / destination arrays of the first template, instantiate
    // and BLAS operation, analysed on the CPU (overlaps, dangling template pointers).
    ComPtr<ID3D12Resource>      capGpu;
    ComPtr<ID3D12Resource>      capRb;
    const uint8_t*              capMapped = nullptr;
    struct Capture {
        uint32_t type, argStride, dstStride, argCount, hasCount, index, convOp, chunkSize;
        uint64_t argOff, dstOff, countOff;
        // BLAS: copy, taken right before the BLAS, of the last instantiate's destination array
        // (where AW2's CLAS address arrays point).
        uint64_t extraVa, extraOff, extraBytes;
    };
    std::vector<Capture>        captures;
    uint64_t                    capUsed     = 0;
    uint32_t                    capTypeMask = 0;
    bool                        capTried    = false;
    bool                        capAnalysed = false;
    // AMD_MG_BLAS_FAKE_CLAS: upload block (vertices, indices, DXR args, destination array,
    // CLAS address array), the built CLAS and its scratch.
    ComPtr<ID3D12Resource>      fakeIn, fakeClas, fakeScratch;
    D3D12_GPU_VIRTUAL_ADDRESS   fakeArrVa   = 0;
    bool                        fakeBuilt   = false;
    bool                        fakeTried   = false;
    // AMD_MG_CAPTURE_REAL: real cluster data of the first BLAS operation (see RecordRealCapture).
    NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_INPUTS capInputs[8] = {};
    ComPtr<ID3D12Resource>      realPlan, realData, realParams, realRb;
    ComPtr<ID3D12CommandSignature> realSig;
    const uint8_t*              realRbMapped = nullptr;
    bool                        realRecorded = false;
    bool                        realWritten  = false;
    uint32_t                    realM = 0, realN = 0, realTc = 0, realIc = 0;
    uint64_t                    realPlanBytes = 0, realDataCap = 0;
    uint64_t                    lastInstDstVa     = 0;
    uint32_t                    lastInstDstStride = 8;
    uint32_t                    lastInstCount     = 0;

    // AMD_MG_SPLIT_OPS: per-operation sequence and chunk progress (dword 0 = last chunk started,
    // dword 1 = last chunk completed, each (convOp << 16) | (chunk + 1)).
    uint32_t                    convOpSeq      = 0;
    uint32_t                    currentConvOp  = 0;
    uint32_t                    currentSplitK  = 0;
    ComPtr<ID3D12Resource>      progressRb;
    volatile uint32_t*          progress       = nullptr;
    bool                        progressTried  = false;
    uint32_t                    splitLoggedTypes = 0;
};

std::mutex g_convMutex;
std::mutex g_blasSizeMutex;
std::map<uint32_t, uint64_t> g_reportedBlasSizes; // clasCount -> largest result size reported
std::unordered_map<ID3D12Device*, DeviceConverterContext> g_deviceContexts;

bool EnsureConverterPipeline(ID3D12Device* pDevice, DeviceConverterContext& ctx) {
    if (ctx.pso && ctx.rootSig) {
        return true;
    }

    D3D12_ROOT_PARAMETER params[4]{};
    params[0].ParameterType            = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
    params[0].Constants.ShaderRegister = 0;
    params[0].Constants.RegisterSpace  = 0;
    params[0].Constants.Num32BitValues = 7;
    params[0].ShaderVisibility         = D3D12_SHADER_VISIBILITY_ALL;

    params[1].ParameterType             = D3D12_ROOT_PARAMETER_TYPE_SRV; // t0: source args
    params[1].Descriptor.ShaderRegister = 0;
    params[1].ShaderVisibility          = D3D12_SHADER_VISIBILITY_ALL;

    params[2].ParameterType             = D3D12_ROOT_PARAMETER_TYPE_UAV; // u0: destination
    params[2].Descriptor.ShaderRegister = 0;
    params[2].ShaderVisibility          = D3D12_SHADER_VISIBILITY_ALL;

    params[3].ParameterType             = D3D12_ROOT_PARAMETER_TYPE_SRV; // t1: GPU argument count
    params[3].Descriptor.ShaderRegister = 1;
    params[3].ShaderVisibility          = D3D12_SHADER_VISIBILITY_ALL;

    D3D12_ROOT_SIGNATURE_DESC rsDesc{};
    rsDesc.NumParameters = 4;
    rsDesc.pParameters   = params;

    ComPtr<ID3DBlob> sigBlob;
    ComPtr<ID3DBlob> errBlob;
    if (FAILED(D3D12SerializeRootSignature(&rsDesc, D3D_ROOT_SIGNATURE_VERSION_1_0, &sigBlob, &errBlob))) {
        Log("[Converter] Failed to serialize root signature");
        return false;
    }
    if (FAILED(pDevice->CreateRootSignature(
            0, sigBlob->GetBufferPointer(), sigBlob->GetBufferSize(), IID_PPV_ARGS(&ctx.rootSig)))) {
        Log("[Converter] Failed to create root signature");
        return false;
    }

    D3D12_COMPUTE_PIPELINE_STATE_DESC psoDesc{};
    psoDesc.pRootSignature = ctx.rootSig.Get();
    psoDesc.CS             = { g_CS_ConvertArgs, sizeof(g_CS_ConvertArgs) };
    if (FAILED(pDevice->CreateComputePipelineState(&psoDesc, IID_PPV_ARGS(&ctx.pso)))) {
        Log("[Converter] Failed to create compute PSO");
        return false;
    }

    // Completion markers (READBACK heap: must stay in COPY_DEST, persistently mapped).
    D3D12_HEAP_PROPERTIES rbHeap{};
    rbHeap.Type = D3D12_HEAP_TYPE_READBACK;
    D3D12_RESOURCE_DESC mDesc{};
    mDesc.Dimension        = D3D12_RESOURCE_DIMENSION_BUFFER;
    mDesc.Width            = kMaxScratchSlots * sizeof(uint32_t);
    mDesc.Height           = 1;
    mDesc.DepthOrArraySize = 1;
    mDesc.MipLevels        = 1;
    mDesc.SampleDesc.Count = 1;
    mDesc.Layout           = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    void* mapped = nullptr;
    if (SUCCEEDED(pDevice->CreateCommittedResource(&rbHeap, D3D12_HEAP_FLAG_NONE, &mDesc,
            D3D12_RESOURCE_STATE_COPY_DEST, nullptr, IID_PPV_ARGS(&ctx.markerBuffer))) &&
        SUCCEEDED(ctx.markerBuffer->Map(0, nullptr, &mapped))) {
        ctx.markers = static_cast<volatile uint32_t*>(mapped);
        for (uint32_t i = 0; i < kMaxScratchSlots; ++i) {
            ctx.markers[i] = 0;
        }
    } else {
        ctx.markerBuffer.Reset();
        Log("[Converter] Failed to create completion marker buffer; using timed scratch release");
    }

    D3D12_FEATURE_DATA_D3D12_OPTIONS3 opt3{};
    if (SUCCEEDED(pDevice->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS3, &opt3, sizeof(opt3)))) {
        ctx.wbiDirect  = (opt3.WriteBufferImmediateSupportFlags & D3D12_COMMAND_LIST_SUPPORT_FLAG_DIRECT) != 0;
        ctx.wbiCompute = (opt3.WriteBufferImmediateSupportFlags & D3D12_COMMAND_LIST_SUPPORT_FLAG_COMPUTE) != 0;
    }
    Log("[Converter] Pipeline ready (WriteBufferImmediate direct=%d compute=%d, markers=%s)",
        ctx.wbiDirect ? 1 : 0, ctx.wbiCompute ? 1 : 0, ctx.markers ? "yes" : "no");
    return true;
}

bool IsSlotFree(const DeviceConverterContext& ctx, uint32_t index, uint64_t nowMs) {
    const ScratchSlot& s = ctx.slots[index];
    if (!s.busy) {
        return true;
    }
    if (s.pendingMarker != 0 && ctx.markers && ctx.markers[index] == s.pendingMarker) {
        return true;
    }
    return s.releaseAfter != 0 && nowMs >= s.releaseAfter;
}

uint64_t RoundUpPow2(uint64_t v) {
    uint64_t r = kMinScratchSize;
    while (r < v) {
        r <<= 1;
    }
    return r;
}

// Returns a slot index whose buffer (state: kScratchCanonicalState) holds >= requiredBytes, or -1.
int AcquireScratchSlot(ID3D12Device* pDevice, DeviceConverterContext& ctx, uint64_t requiredBytes) {
    const uint64_t need  = RoundUpPow2(requiredBytes);
    const uint64_t nowMs = GetTickCount64();

    int best = -1;
    int anyFree = -1;
    for (uint32_t i = 0; i < ctx.slots.size(); ++i) {
        if (!IsSlotFree(ctx, i, nowMs)) {
            continue;
        }
        if (anyFree < 0) {
            anyFree = static_cast<int>(i);
        }
        if (ctx.slots[i].size >= need && (best < 0 || ctx.slots[i].size < ctx.slots[best].size)) {
            best = static_cast<int>(i);
        }
    }

    if (best < 0) {
        if (ctx.slots.size() < kMaxScratchSlots) {
            ctx.slots.emplace_back();
            best = static_cast<int>(ctx.slots.size() - 1);
        } else if (anyFree >= 0) {
            best = anyFree; // GPU is done with it: safe to release and grow
        } else {
            if (!ctx.warnedPoolFull) {
                Log("[Converter] Scratch pool exhausted (%u slots in flight)", kMaxScratchSlots);
                ctx.warnedPoolFull = true;
            }
            return -1;
        }
    }

    ScratchSlot& slot = ctx.slots[best];
    if (!slot.buffer || slot.size < need) {
        slot.buffer.Reset();
        slot.size = 0;

        D3D12_HEAP_PROPERTIES heapProps{};
        heapProps.Type = D3D12_HEAP_TYPE_DEFAULT;
        D3D12_RESOURCE_DESC bufDesc{};
        bufDesc.Dimension        = D3D12_RESOURCE_DIMENSION_BUFFER;
        bufDesc.Width            = need;
        bufDesc.Height           = 1;
        bufDesc.DepthOrArraySize = 1;
        bufDesc.MipLevels        = 1;
        bufDesc.SampleDesc.Count = 1;
        bufDesc.Layout           = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
        bufDesc.Flags            = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
        if (FAILED(pDevice->CreateCommittedResource(&heapProps, D3D12_HEAP_FLAG_NONE, &bufDesc,
                kScratchCanonicalState, nullptr, IID_PPV_ARGS(&slot.buffer)))) {
            Log("[Converter] Failed to allocate %llu bytes of GPU scratch", need);
            slot.buffer.Reset();
            return -1;
        }
        slot.size = need;
        const uint64_t va = slot.buffer->GetGPUVirtualAddress();
        Log("[Converter] scratch slot %d: %llu bytes at [0x%llx..0x%llx)", best,
            static_cast<unsigned long long>(need), static_cast<unsigned long long>(va),
            static_cast<unsigned long long>(va + need));
    }
    slot.busy          = true;
    slot.pendingMarker = 0;
    slot.releaseAfter  = 0;
    return best;
}

// AMD_MG_SANITIZE_DST=0 passes the game's destination array to DXR untouched (default: copy it
// and redirect null entries, which crash the AMD driver; see .agent/architecture.md).
bool SanitizeDstEnabled() {
    static const bool enabled = [] {
        char value[8] = {};
        const DWORD len = GetEnvironmentVariableA("AMD_MG_SANITIZE_DST", value, sizeof(value));
        const bool on = !(len > 0 && len < sizeof(value) && std::atoi(value) == 0);
        Log("[Converter] Null destination redirect %s (AMD_MG_SANITIZE_DST)", on ? "enabled" : "DISABLED");
        return on;
    }();
    return enabled;
}

// Sink for results whose destination address is null: big enough for any single cluster
// object of an unused slot, in the acceleration-structure state DXR requires for results.
constexpr uint64_t kNullDstSinkBytes = 8ull * 1024ull * 1024ull;

bool EnsureNullDstSink(ID3D12Device* pDevice, DeviceConverterContext& ctx) {
    if (ctx.nullDstSink) {
        return true;
    }
    D3D12_HEAP_PROPERTIES hp{};
    hp.Type = D3D12_HEAP_TYPE_DEFAULT;
    D3D12_RESOURCE_DESC d{};
    d.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
    d.Width = kNullDstSinkBytes;
    d.Height = 1; d.DepthOrArraySize = 1; d.MipLevels = 1; d.SampleDesc.Count = 1;
    d.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    d.Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
    if (FAILED(pDevice->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d,
            D3D12_RESOURCE_STATE_RAYTRACING_ACCELERATION_STRUCTURE, nullptr, IID_PPV_ARGS(&ctx.nullDstSink)))) {
        if (!ctx.warnedDstSanitize) {
            Log("[Converter] WARNING: could not allocate the null-destination sink");
            ctx.warnedDstSanitize = true;
        }
        return false;
    }
    ctx.nullDstSink->SetName(L"amd_mg null-destination sink");
    Log("[Converter] null-destination sink at [0x%llx..0x%llx)",
        static_cast<unsigned long long>(ctx.nullDstSink->GetGPUVirtualAddress()),
        static_cast<unsigned long long>(ctx.nullDstSink->GetGPUVirtualAddress() + kNullDstSinkBytes));
    return true;
}

void Transition(ID3D12GraphicsCommandList* pCmdList, ID3D12Resource* res,
                D3D12_RESOURCE_STATES before, D3D12_RESOURCE_STATES after) {
    D3D12_RESOURCE_BARRIER b{};
    b.Type                   = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    b.Transition.pResource   = res;
    b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    b.Transition.StateBefore = before;
    b.Transition.StateAfter  = after;
    pCmdList->ResourceBarrier(1, &b);
}

void GlobalUavBarrier(ID3D12GraphicsCommandList* pCmdList) {
    D3D12_RESOURCE_BARRIER b{};
    b.Type          = D3D12_RESOURCE_BARRIER_TYPE_UAV;
    b.UAV.pResource = nullptr;
    pCmdList->ResourceBarrier(1, &b);
}

void DispatchConversionCS(
    ID3D12GraphicsCommandList* pCmdList,
    DeviceConverterContext& ctx,
    D3D12_GPU_VIRTUAL_ADDRESS srcAddr,
    D3D12_GPU_VIRTUAL_ADDRESS dstAddr,
    D3D12_GPU_VIRTUAL_ADDRESS countAddr,
    uint32_t maxOps,
    uint32_t srcStride,
    uint32_t dstStride,
    uint32_t mode,
    uint64_t extra = 0)
{
    // NOTE: this replaces the compute root signature / PSO bound on the game's command list.
    // nvrhi re-binds after every cluster operation; engines that do not would need state
    // shadowing (see .agent/architecture.md "Limiti noti").
    pCmdList->SetComputeRootSignature(ctx.rootSig.Get());
    pCmdList->SetPipelineState(ctx.pso.Get());

    uint32_t constants[7] = { maxOps, srcStride, dstStride, mode, countAddr != 0 ? 1u : 0u,
                              static_cast<uint32_t>(extra), static_cast<uint32_t>(extra >> 32) };
    pCmdList->SetComputeRoot32BitConstants(0, 7, constants, 0);
    pCmdList->SetComputeRootShaderResourceView(1, srcAddr);
    pCmdList->SetComputeRootUnorderedAccessView(2, dstAddr);
    pCmdList->SetComputeRootShaderResourceView(3, countAddr != 0 ? countAddr : srcAddr);
    pCmdList->Dispatch((maxOps + 63u) / 64u, 1, 1);
}

void RecordSlotCompletion(ID3D12GraphicsCommandList* pCmdList, DeviceConverterContext& ctx,
                          const int* slotIndices, uint32_t count) {
    const D3D12_COMMAND_LIST_TYPE type = pCmdList->GetType();
    const bool wbiSupported = ctx.markers &&
        ((type == D3D12_COMMAND_LIST_TYPE_DIRECT && ctx.wbiDirect) ||
         (type == D3D12_COMMAND_LIST_TYPE_COMPUTE && ctx.wbiCompute));
    ComPtr<ID3D12GraphicsCommandList2> pList2;
    if (wbiSupported) {
        pCmdList->QueryInterface(IID_PPV_ARGS(&pList2));
    }

    D3D12_WRITEBUFFERIMMEDIATE_PARAMETER params[4]{};
    D3D12_WRITEBUFFERIMMEDIATE_MODE      modes[4]{};
    uint32_t n = 0;
    for (uint32_t k = 0; k < count && k < 4; ++k) {
        const int idx = slotIndices[k];
        if (idx < 0) {
            continue;
        }
        ScratchSlot& slot = ctx.slots[idx];
        if (pList2) {
            uint32_t value = ++ctx.nextMarker;
            if (value == 0) {
                value = ++ctx.nextMarker;
            }
            slot.pendingMarker = value;
            params[n].Dest  = ctx.markerBuffer->GetGPUVirtualAddress() + idx * sizeof(uint32_t);
            params[n].Value = value;
            modes[n]        = D3D12_WRITEBUFFERIMMEDIATE_MODE_MARKER_OUT;
            ++n;
        } else {
            slot.releaseAfter = GetTickCount64() + kTimedReleaseMs;
        }
    }
    if (pList2 && n > 0) {
        pList2->WriteBufferImmediate(n, params, modes);
    }
}

// ---------------------------------------------------------------------------
// AMD_MG_DUMP_ARGS: copy the first entries of each operation's arrays to a readback buffer
// before the operation runs, and log them decoded. The copy lands even if the operation
// itself later faults the GPU, so the DRED dump can print what the game actually passed.
// ---------------------------------------------------------------------------
constexpr uint32_t kDumpSlots      = 16;
constexpr uint32_t kDumpSlotBytes  = 16384;
constexpr uint32_t kDumpArgBytes   = 8192;
constexpr uint32_t kDumpDstOffset  = 8192;
constexpr uint32_t kDumpDstBytes   = 2048;
constexpr uint32_t kDumpCountOff   = 10240;
constexpr uint32_t kDumpStatsOff   = 12288; // 32 dwords written by the full-array scan (modes 7/8/9)
constexpr uint32_t kDumpStatsBytes = 128;
constexpr uint32_t kDumpSentinel   = kDumpSlotBytes - 4;
constexpr uint32_t kDumpsPerType   = 3;

bool DumpArgsEnabled() {
    char value[8] = {};
    const DWORD len = GetEnvironmentVariableA("AMD_MG_DUMP_ARGS", value, sizeof(value));
    // Default on (2 small copies per operation type for the whole run); AMD_MG_DUMP_ARGS=0 disables.
    return !(len > 0 && len < sizeof(value) && std::atoi(value) == 0);
}

bool EnsureDumpBuffers(ID3D12Device* dev, DeviceConverterContext& ctx) {
    if (ctx.dumpMapped) {
        return true;
    }
    if (ctx.dumpTried) {
        return false;
    }
    ctx.dumpTried = true;
    D3D12_RESOURCE_DESC d{};
    d.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
    d.Width = static_cast<UINT64>(kDumpSlots) * kDumpSlotBytes;
    d.Height = 1; d.DepthOrArraySize = 1; d.MipLevels = 1; d.SampleDesc.Count = 1;
    d.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    D3D12_HEAP_PROPERTIES hp{};
    hp.Type = D3D12_HEAP_TYPE_DEFAULT;
    d.Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
    if (FAILED(dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d, D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
                                            nullptr, IID_PPV_ARGS(&ctx.dumpGpu)))) {
        return false;
    }
    hp.Type = D3D12_HEAP_TYPE_READBACK;
    d.Flags = D3D12_RESOURCE_FLAG_NONE;
    void* mapped = nullptr;
    if (FAILED(dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d, D3D12_RESOURCE_STATE_COPY_DEST,
                                            nullptr, IID_PPV_ARGS(&ctx.dumpRb))) ||
        FAILED(ctx.dumpRb->Map(0, nullptr, &mapped))) {
        ctx.dumpGpu.Reset();
        return false;
    }
    ctx.dumpMapped = static_cast<const uint8_t*>(mapped);
    std::memset(mapped, 0, static_cast<size_t>(d.Width));
    Log("[Dump] Argument dumps enabled (%u per operation type, AMD_MG_DUMP_ARGS=0 disables)", kDumpsPerType);
    return true;
}

void LogDump(const DeviceConverterContext& ctx, const DeviceConverterContext::PendingDump& pd, bool complete) {
    const uint8_t* base = ctx.dumpMapped + static_cast<size_t>(pd.slot) * kDumpSlotBytes;
    auto u32 = [&](uint32_t off) { uint32_t v; std::memcpy(&v, base + off, 4); return v; };
    auto u64 = [&](uint32_t off) { uint64_t v; std::memcpy(&v, base + off, 8); return v; };
    const uint32_t count = pd.hasCount ? u32(kDumpCountOff) : pd.argCount;
    const uint32_t n = std::min(pd.argCount, std::min<uint32_t>(count, 64u));
    Log("[Dump] #%u type=%u mode=%u%s args(VA=0x%llx stride=%u) dst(VA=0x%llx stride=%u) count=%u%s (dumped %u)",
        pd.seq, pd.type, pd.mode, complete ? "" : " [INCOMPLETE: GPU did not confirm the copy]",
        static_cast<unsigned long long>(pd.argVa), pd.argStride,
        static_cast<unsigned long long>(pd.dstVa), pd.dstStride, count,
        pd.hasCount ? " (GPU count)" : " (maxArgCount)", n);

    {
        // Full-array scan (every argument up to the effective count, and the whole dst array).
        auto st = [&](uint32_t i) { return u32(kDumpStatsOff + i * 4); };
        const uint32_t firstBad = st(7), lastBad = st(8);
        char badRange[64] = "none";
        if (firstBad != 0xFFFFFFFFu) {
            std::snprintf(badRange, sizeof(badRange), "%u..%u", firstBad, lastBad);
        }
        Log("[Dump]   scan: %u args | empty=%u vtx0=%u nullPtr=%u nullVb=%u over256=%u badFmt/stride0=%u | bad idx %s"
            " | ptr hi32 [0x%x..0x%x] align>=2^%u | max=%u sum=%u",
            st(0), st(1), st(2), st(3), st(4), st(5), st(6), badRange, st(9) == 0xFFFFFFFFu ? 0 : st(9), st(10),
            st(13) == 0xFFFFFFFFu ? 0 : st(13), st(11), st(12));
        if (pd.dstVa) {
            char firstNull[24] = "-";
            if (st(17) != 0xFFFFFFFFu) {
                std::snprintf(firstNull, sizeof(firstNull), "%u", st(17));
            }
            Log("[Dump]   scan dst: null=%u (first at %s) | hi32 [0x%x..0x%x] align>=2^%u",
                st(16), firstNull, st(18) == 0xFFFFFFFFu ? 0 : st(18), st(19), st(20) == 0xFFFFFFFFu ? 0 : st(20));
        }
    }

    uint64_t lo[4] = { ~0ull, ~0ull, ~0ull, ~0ull }, hi[4] = {};
    auto range = [&](int k, uint64_t v) { if (v) { lo[k] = std::min(lo[k], v); hi[k] = std::max(hi[k], v); } };
    for (uint32_t i = 0; i < n; ++i) {
        const uint32_t o = i * pd.argStride;
        if (o + pd.argStride > kDumpArgBytes) break;
        char line[400] = {};
        switch (pd.type) {
        case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_CLAS_FROM_TRIANGLES:
        case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_CLUSTER_TEMPLATES_FROM_TRIANGLES: {
            const uint32_t packed = u32(o + 8);
            const uint32_t strides0 = u32(o + 16), strides1 = u32(o + 20);
            const uint64_t ib = u64(o + 24), vb = u64(o + 32), gb = u64(o + 40), bbox = pd.argStride >= 72 ? u64(o + 64) : 0;
            range(0, ib); range(1, vb); range(2, bbox);
            std::snprintf(line, sizeof(line),
                "id=%u flags=0x%x tri=%u vtx=%u trunc=%u idxFmt=%u ommFmt=%u geom=0x%x istride=%u vstride=%u gstride=%u ib=0x%llx vb=0x%llx geomBuf=0x%llx omm=0x%llx bbox=0x%llx",
                u32(o), u32(o + 4), packed & 0x1FF, (packed >> 9) & 0x1FF, (packed >> 18) & 0x3F, (packed >> 24) & 0xF,
                (packed >> 28) & 0xF, u32(o + 12), strides0 & 0xFFFF, strides0 >> 16, strides1 & 0xFFFF,
                static_cast<unsigned long long>(ib), static_cast<unsigned long long>(vb), static_cast<unsigned long long>(gb),
                static_cast<unsigned long long>(u64(o + 48)), static_cast<unsigned long long>(bbox));
            break;
        }
        case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_INSTANTIATE_CLUSTER_TEMPLATES: {
            const uint64_t tpl = u64(o + 8), vb = u64(o + 16), vs = u64(o + 24);
            range(0, tpl); range(1, vb);
            std::snprintf(line, sizeof(line), "clusterIdOffset=%u geomOffset=%u template=0x%llx vb=0x%llx vstride=%llu",
                u32(o), u32(o + 4), static_cast<unsigned long long>(tpl), static_cast<unsigned long long>(vb),
                static_cast<unsigned long long>(vs));
            break;
        }
        case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_BLAS_FROM_CLAS: {
            const uint64_t arr = u64(o + 8);
            range(0, arr);
            std::snprintf(line, sizeof(line), "clasCount=%u reserved=%u clasArray=0x%llx", u32(o), u32(o + 4),
                static_cast<unsigned long long>(arr));
            break;
        }
        default:
            std::snprintf(line, sizeof(line), "raw %08x %08x %08x %08x", u32(o), u32(o + 4), u32(o + 8), u32(o + 12));
            break;
        }
        if (i < 8) {
            Log("[Dump]   arg[%u] %s", i, line);
        }
    }
    Log("[Dump]   ranges over %u args: A=[0x%llx..0x%llx] B=[0x%llx..0x%llx] C=[0x%llx..0x%llx]"
        " (templates/clusters: A=index buffers|templates|CLAS arrays, B=vertex buffers, C=bbox)", n,
        static_cast<unsigned long long>(lo[0] == ~0ull ? 0 : lo[0]), static_cast<unsigned long long>(hi[0]),
        static_cast<unsigned long long>(lo[1] == ~0ull ? 0 : lo[1]), static_cast<unsigned long long>(hi[1]),
        static_cast<unsigned long long>(lo[2] == ~0ull ? 0 : lo[2]), static_cast<unsigned long long>(hi[2]));
    if (pd.dstVa) {
        const uint32_t ds = pd.dstStride ? pd.dstStride : 8;
        uint64_t dlo = ~0ull, dhi = 0;
        uint32_t zeros = 0;
        std::string first;
        for (uint32_t i = 0; i < n && i * ds + 8 <= kDumpDstBytes; ++i) {
            const uint64_t v = u64(kDumpDstOffset + i * ds);
            if (!v) { ++zeros; continue; }
            dlo = std::min(dlo, v); dhi = std::max(dhi, v);
            if (i < 6) { char b[32]; std::snprintf(b, sizeof(b), " 0x%llx", static_cast<unsigned long long>(v)); first += b; }
        }
        Log("[Dump]   dst:%s ... range [0x%llx..0x%llx], %u null", first.c_str(),
            static_cast<unsigned long long>(dlo == ~0ull ? 0 : dlo), static_cast<unsigned long long>(dhi), zeros);
    }
}

void FlushDumpsLocked(DeviceConverterContext& ctx, bool force) {
    if (!ctx.dumpMapped) {
        return;
    }
    for (size_t i = 0; i < ctx.pendingDumps.size();) {
        const auto& pd = ctx.pendingDumps[i];
        uint32_t sentinel;
        std::memcpy(&sentinel, ctx.dumpMapped + static_cast<size_t>(pd.slot) * kDumpSlotBytes + kDumpSentinel, 4);
        const bool done = sentinel == (0xD0D00000u | pd.seq);
        if (done || force) {
            LogDump(ctx, pd, done);
            ctx.pendingDumps.erase(ctx.pendingDumps.begin() + static_cast<ptrdiff_t>(i));
        } else {
            ++i;
        }
    }
}

void RecordArgDump(ID3D12GraphicsCommandList* cl, ID3D12Device* dev, DeviceConverterContext& ctx,
                   const NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_DESC& d) {
    const uint32_t type = static_cast<uint32_t>(d.inputs.type) & 7u;
    if (ctx.dumpsPerType[type] >= kDumpsPerType || ctx.pendingDumps.size() >= kDumpSlots ||
        !EnsureDumpBuffers(dev, ctx) || d.indirectArgArray.StartAddress == 0) {
        return;
    }
    // Free slot index
    uint32_t slot = 0;
    for (; slot < kDumpSlots; ++slot) {
        bool used = false;
        for (const auto& p : ctx.pendingDumps) used |= (p.slot == slot);
        if (!used) break;
    }
    if (slot == kDumpSlots) return;
    ++ctx.dumpsPerType[type];

    DeviceConverterContext::PendingDump pd{};
    pd.slot = slot; pd.type = d.inputs.type; pd.mode = d.inputs.mode;
    pd.argStride = static_cast<uint32_t>(d.indirectArgArray.StrideInBytes);
    if (pd.argStride == 0) {
        pd.argStride = d.inputs.type == NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_CLUSTER_TEMPLATES_FROM_TRIANGLES ? 72u
                     : d.inputs.type == NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_CLAS_FROM_TRIANGLES ? 64u
                     : d.inputs.type == NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_INSTANTIATE_CLUSTER_TEMPLATES ? 32u
                     : d.inputs.type == NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_BLAS_FROM_CLAS ? 16u : 8u;
    }
    pd.dstStride = static_cast<uint32_t>(d.destinationAddressArray.StrideInBytes);
    pd.argCount = d.inputs.maxArgCount;
    pd.hasCount = d.indirectArgCount != 0;
    pd.argVa = d.indirectArgArray.StartAddress;
    pd.dstVa = (d.inputs.mode == NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_MODE_EXPLICIT_DESTINATIONS)
        ? d.destinationAddressArray.StartAddress : 0;
    pd.countVa = d.indirectArgCount;
    pd.seq = ++ctx.dumpSeq & 0xFFFFu;

    const D3D12_GPU_VIRTUAL_ADDRESS out = ctx.dumpGpu->GetGPUVirtualAddress() + static_cast<uint64_t>(slot) * kDumpSlotBytes;
    const uint32_t argDwords = std::min<uint64_t>(static_cast<uint64_t>(std::min(pd.argCount, 64u)) * pd.argStride, kDumpArgBytes) / 4;
    DispatchConversionCS(cl, ctx, pd.argVa, out, 0, argDwords, 4, 4, 6);
    if (pd.dstVa) {
        const uint32_t ds = pd.dstStride ? pd.dstStride : 8;
        const uint32_t dstDwords = std::min<uint64_t>(static_cast<uint64_t>(std::min(pd.argCount, 64u)) * ds, kDumpDstBytes) / 4;
        DispatchConversionCS(cl, ctx, pd.dstVa, out + kDumpDstOffset, 0, dstDwords, 4, 4, 6);
    }
    if (pd.countVa) {
        DispatchConversionCS(cl, ctx, pd.countVa & ~3ull, out + kDumpCountOff, 0, 1, 4, 4, 6);
    }
    // Scan every argument and destination address (statistics only, nothing is modified).
    DispatchConversionCS(cl, ctx, pd.argVa, out + kDumpStatsOff, 0, kDumpStatsBytes / 4, 4, 4, 9);
    GlobalUavBarrier(cl);
    DispatchConversionCS(cl, ctx, pd.argVa, out + kDumpStatsOff, pd.countVa, pd.argCount, pd.argStride, pd.type, 7);
    if (pd.dstVa) {
        DispatchConversionCS(cl, ctx, pd.dstVa, out + kDumpStatsOff, pd.countVa, pd.argCount,
                             pd.dstStride ? pd.dstStride : 8, 0, 8);
    }
    GlobalUavBarrier(cl);
    Transition(cl, ctx.dumpGpu.Get(), D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    cl->CopyBufferRegion(ctx.dumpRb.Get(), static_cast<uint64_t>(slot) * kDumpSlotBytes, ctx.dumpGpu.Get(),
                         static_cast<uint64_t>(slot) * kDumpSlotBytes, kDumpStatsOff + kDumpStatsBytes);
    Transition(cl, ctx.dumpGpu.Get(), D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    ComPtr<ID3D12GraphicsCommandList2> l2;
    if (SUCCEEDED(cl->QueryInterface(IID_PPV_ARGS(&l2))) && l2) {
        D3D12_WRITEBUFFERIMMEDIATE_PARAMETER prm{};
        prm.Dest  = ctx.dumpRb->GetGPUVirtualAddress() + static_cast<uint64_t>(slot) * kDumpSlotBytes + kDumpSentinel;
        prm.Value = 0xD0D00000u | pd.seq;
        D3D12_WRITEBUFFERIMMEDIATE_MODE m = D3D12_WRITEBUFFERIMMEDIATE_MODE_MARKER_OUT;
        l2->WriteBufferImmediate(1, &prm, &m);
    }
    ctx.pendingDumps.push_back(pd);
}

// ---------------------------------------------------------------------------
// Layout capture (AMD_MG_DUMP_ARGS): the complete argument and destination arrays of the first
// template build, instantiation and BLAS build are copied to a readback buffer and analysed on
// the CPU once the copies landed (or at device removal): duplicate / overlapping destinations,
// gaps between packed objects, instances pointing at addresses that are not built templates,
// instantiated CLAS written over templates.
// ---------------------------------------------------------------------------
constexpr uint64_t kCapBytes       = 32ull << 20;
constexpr uint64_t kCapSentinelOff = kCapBytes - 256; // one uint32 per capture
constexpr uint32_t kCapMax         = 16;
constexpr uint64_t kCapMaxDwords   = 65535ull * 64ull; // one dispatch

constexpr uint32_t kTypeBlasFromClas = NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_BLAS_FROM_CLAS;
constexpr uint32_t kTypeTemplates    = NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_CLUSTER_TEMPLATES_FROM_TRIANGLES;
constexpr uint32_t kTypeInstantiate  = NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_INSTANTIATE_CLUSTER_TEMPLATES;

uint64_t AlignUp(uint64_t v, uint64_t a) { return (v + a - 1) & ~(a - 1); }

bool EnsureCaptureBuffers(ID3D12Device* dev, DeviceConverterContext& ctx) {
    if (ctx.capMapped) {
        return true;
    }
    if (ctx.capTried) {
        return false;
    }
    ctx.capTried = true;
    D3D12_RESOURCE_DESC d{};
    d.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
    d.Width = kCapBytes;
    d.Height = 1; d.DepthOrArraySize = 1; d.MipLevels = 1; d.SampleDesc.Count = 1;
    d.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    D3D12_HEAP_PROPERTIES hp{};
    hp.Type = D3D12_HEAP_TYPE_DEFAULT;
    d.Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
    if (FAILED(dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d, D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
                                            nullptr, IID_PPV_ARGS(&ctx.capGpu)))) {
        return false;
    }
    hp.Type = D3D12_HEAP_TYPE_READBACK;
    d.Flags = D3D12_RESOURCE_FLAG_NONE;
    void* mapped = nullptr;
    if (FAILED(dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d, D3D12_RESOURCE_STATE_COPY_DEST,
                                            nullptr, IID_PPV_ARGS(&ctx.capRb))) ||
        FAILED(ctx.capRb->Map(0, nullptr, &mapped))) {
        ctx.capGpu.Reset();
        return false;
    }
    ctx.capMapped = static_cast<const uint8_t*>(mapped);
    std::memset(mapped, 0, static_cast<size_t>(kCapBytes));
    Log("[Layout] Layout capture enabled (first template / instantiate / BLAS operation, %llu MB)",
        static_cast<unsigned long long>(kCapBytes >> 20));
    return true;
}

void RecordLayoutCapture(ID3D12GraphicsCommandList* cl, ID3D12Device* dev, DeviceConverterContext& ctx,
                         const NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_DESC& d) {
    const uint32_t type = static_cast<uint32_t>(d.inputs.type);
    if (type != kTypeTemplates && type != kTypeInstantiate && type != kTypeBlasFromClas) return;
    if (type == kTypeInstantiate && d.destinationAddressArray.StartAddress) {
        ctx.lastInstDstVa     = d.destinationAddressArray.StartAddress;
        ctx.lastInstDstStride = d.destinationAddressArray.StrideInBytes ? static_cast<uint32_t>(d.destinationAddressArray.StrideInBytes) : 8u;
        ctx.lastInstCount     = d.inputs.maxArgCount;
    }
    if (ctx.capAnalysed || (ctx.capTypeMask & (1u << type)) || ctx.captures.size() >= kCapMax) return;
    if (d.inputs.mode != NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_MODE_EXPLICIT_DESTINATIONS ||
        !d.indirectArgArray.StartAddress || !d.destinationAddressArray.StartAddress || d.inputs.maxArgCount == 0) {
        return;
    }
    if (!EnsureCaptureBuffers(dev, ctx)) return;
    ctx.capTypeMask |= 1u << type;
    ctx.capInputs[type & 7u] = d.inputs;

    DeviceConverterContext::Capture c{};
    c.type      = type;
    c.argStride = static_cast<uint32_t>(d.indirectArgArray.StrideInBytes);
    if (c.argStride == 0) {
        c.argStride = type == kTypeTemplates ? 72u : type == kTypeInstantiate ? 32u : 16u;
    }
    c.dstStride = d.destinationAddressArray.StrideInBytes ? static_cast<uint32_t>(d.destinationAddressArray.StrideInBytes) : 8u;
    c.argCount  = d.inputs.maxArgCount;
    c.hasCount  = d.indirectArgCount != 0;
    const uint64_t argBytes = static_cast<uint64_t>(c.argCount) * c.argStride;
    const uint64_t dstBytes = static_cast<uint64_t>(c.argCount) * c.dstStride;
    c.argOff   = ctx.capUsed;
    c.dstOff   = AlignUp(c.argOff + argBytes, 256);
    c.countOff = AlignUp(c.dstOff + dstBytes, 256);
    uint64_t end = c.countOff + 256;
    if (type == kTypeBlasFromClas && ctx.lastInstDstVa && ctx.lastInstDstStride == 8) {
        c.extraVa    = ctx.lastInstDstVa;
        c.extraBytes = static_cast<uint64_t>(ctx.lastInstCount) * 8u;
        c.extraOff   = end;
        if (c.extraBytes / 4 <= kCapMaxDwords && c.extraOff + c.extraBytes + 256 <= kCapSentinelOff) {
            end = AlignUp(c.extraOff + c.extraBytes, 256);
        } else {
            c.extraVa = c.extraOff = c.extraBytes = 0;
        }
    }
    if (end > kCapSentinelOff || argBytes / 4 > kCapMaxDwords || dstBytes / 4 > kCapMaxDwords) {
        Log("[Layout] type=%u: %u args too large to capture", type, c.argCount);
        return;
    }
    c.index = static_cast<uint32_t>(ctx.captures.size());
    c.convOp = ctx.currentConvOp;
    c.chunkSize = ctx.currentSplitK;
    ctx.capUsed = end;

    const D3D12_GPU_VIRTUAL_ADDRESS base = ctx.capGpu->GetGPUVirtualAddress();
    DispatchConversionCS(cl, ctx, d.indirectArgArray.StartAddress, base + c.argOff, d.indirectArgCount,
                         static_cast<uint32_t>(argBytes / 4), c.argStride, 4, 11);
    DispatchConversionCS(cl, ctx, d.destinationAddressArray.StartAddress, base + c.dstOff, d.indirectArgCount,
                         static_cast<uint32_t>(dstBytes / 4), c.dstStride, 4, 11);
    if (c.hasCount) {
        DispatchConversionCS(cl, ctx, d.indirectArgCount & ~3ull, base + c.countOff, 0, 1, 4, 4, 6);
    }
    if (c.extraBytes) {
        DispatchConversionCS(cl, ctx, c.extraVa, base + c.extraOff, 0, static_cast<uint32_t>(c.extraBytes / 4), 4, 4, 11);
    }
    GlobalUavBarrier(cl);
    Transition(cl, ctx.capGpu.Get(), D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    cl->CopyBufferRegion(ctx.capRb.Get(), c.argOff, ctx.capGpu.Get(), c.argOff, end - c.argOff);
    Transition(cl, ctx.capGpu.Get(), D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    ComPtr<ID3D12GraphicsCommandList2> l2;
    if (SUCCEEDED(cl->QueryInterface(IID_PPV_ARGS(&l2))) && l2) {
        D3D12_WRITEBUFFERIMMEDIATE_PARAMETER prm{};
        prm.Dest  = ctx.capRb->GetGPUVirtualAddress() + kCapSentinelOff + c.index * 4ull;
        prm.Value = 0xCA900000u | c.index;
        D3D12_WRITEBUFFERIMMEDIATE_MODE m = D3D12_WRITEBUFFERIMMEDIATE_MODE_MARKER_OUT;
        l2->WriteBufferImmediate(1, &prm, &m);
    }
    ctx.captures.push_back(c);
}

// Sorted distinct addresses; gap(k) = distance to the next distinct address.
struct SortedAddrs {
    std::vector<uint64_t> a;
    uint32_t nulls = 0, dups = 0;
    explicit SortedAddrs(std::vector<uint64_t> v) {
        std::sort(v.begin(), v.end());
        for (uint64_t x : v) {
            if (!x) { ++nulls; continue; }
            if (!a.empty() && a.back() == x) { ++dups; continue; }
            a.push_back(x);
        }
    }
    uint64_t gap(size_t k) const { return k + 1 < a.size() ? a[k + 1] - a[k] : ~0ull; }
    // Index of the greatest address <= v, or -1.
    ptrdiff_t floor(uint64_t v) const {
        auto it = std::upper_bound(a.begin(), a.end(), v);
        return it == a.begin() ? -1 : (it - a.begin()) - 1;
    }
    // Index of the smallest address >= v, or -1.
    ptrdiff_t ceil(uint64_t v) const {
        auto it = std::lower_bound(a.begin(), a.end(), v);
        return it == a.end() ? -1 : it - a.begin();
    }
};

void LogGaps(const char* what, const SortedAddrs& s) {
    static const uint64_t edges[] = { 1024, 2048, 3072, 4096, 5120, 6144, 7168, 8192 };
    uint32_t hist[9] = {};
    uint64_t mn = ~0ull;
    for (size_t k = 0; k + 1 < s.a.size(); ++k) {
        const uint64_t g = s.gap(k);
        mn = std::min(mn, g);
        size_t b = 0;
        while (b < 8 && g >= edges[b]) ++b;
        ++hist[b];
    }
    Log("[Layout]   %s: %zu distinct, null=%u, duplicates=%u, range [0x%llx..0x%llx], min gap to next=%llu",
        what, s.a.size(), s.nulls, s.dups, static_cast<unsigned long long>(s.a.empty() ? 0 : s.a.front()),
        static_cast<unsigned long long>(s.a.empty() ? 0 : s.a.back()),
        static_cast<unsigned long long>(mn == ~0ull ? 0 : mn));
    Log("[Layout]   %s gaps: <1K %u | <2K %u | <3K %u | <4K %u | <5K %u | <6K %u | <7K %u | <8K %u | >=8K %u",
        what, hist[0], hist[1], hist[2], hist[3], hist[4], hist[5], hist[6], hist[7], hist[8]);
}

void WriteRealCapture(DeviceConverterContext& ctx);

void AnalyseLayoutLocked(DeviceConverterContext& ctx, bool force) {
    if (!ctx.capMapped || ctx.capAnalysed || ctx.captures.empty()) return;
    const uint8_t* m = ctx.capMapped;
    auto U32 = [&](uint64_t off) { uint32_t v; std::memcpy(&v, m + off, 4); return v; };
    auto U64 = [&](uint64_t off) { uint64_t v; std::memcpy(&v, m + off, 8); return v; };
    auto done = [&](const DeviceConverterContext::Capture& c) {
        return U32(kCapSentinelOff + c.index * 4ull) == (0xCA900000u | c.index);
    };
    const DeviceConverterContext::Capture* tc = nullptr;
    const DeviceConverterContext::Capture* ic = nullptr;
    const DeviceConverterContext::Capture* bc = nullptr;
    bool allDone = true;
    for (const auto& c : ctx.captures) {
        allDone &= done(c);
        if (c.type == kTypeTemplates) tc = &c;
        if (c.type == kTypeInstantiate) ic = &c;
        if (c.type == kTypeBlasFromClas) bc = &c;
    }
    if (!force && !(tc && ic && allDone)) return;
    ctx.capAnalysed = true;
    auto count = [&](const DeviceConverterContext::Capture& c) {
        return c.hasCount ? std::min(c.argCount, U32(c.countOff)) : c.argCount;
    };
    Log("[Layout] ===== Layout analysis%s =====", force ? " (device removal)" : "");
    for (const auto& c : ctx.captures) {
        Log("[Layout] capture type=%u: %u of %u args%s%s", c.type, count(c), c.argCount, c.hasCount ? " (GPU count)" : "",
            done(c) ? "" : " [INCOMPLETE: GPU did not confirm the copy]");
    }

    // --- Templates -------------------------------------------------------------------------
    struct Tpl { uint64_t dst; uint32_t i, tri, vtx; uint64_t ib, vb; uint32_t id, flags, packed, geom, strides; };
    std::vector<Tpl> tpls;
    std::unique_ptr<SortedAddrs> tplAddrs;
    if (tc) {
        const uint32_t n = count(*tc);
        std::vector<uint64_t> dsts;
        uint32_t ibOdd = 0, ibNot4 = 0;
        for (uint32_t i = 0; i < n; ++i) {
            const uint64_t o = tc->argOff + static_cast<uint64_t>(i) * tc->argStride;
            const uint32_t packed = U32(o + 8);
            const uint64_t ib = U64(o + 24);
            const uint64_t dst = U64(tc->dstOff + static_cast<uint64_t>(i) * tc->dstStride);
            if (ib & 1) ++ibOdd;
            if (ib & 3) ++ibNot4;
            tpls.push_back({ dst, i, packed & 0x1FFu, (packed >> 9) & 0x1FFu, ib, U64(o + 32),
                             U32(o), U32(o + 4), packed, U32(o + 12), U32(o + 16) });
            dsts.push_back(dst);
        }
        tplAddrs = std::make_unique<SortedAddrs>(dsts);
        Log("[Layout] templates: %u args, index buffers not 4-byte aligned=%u (odd=%u)", n, ibNot4, ibOdd);
        LogGaps("template dst", *tplAddrs);
        // Smallest gaps relative to the template's triangle count, and minimum gap per triangle band.
        std::sort(tpls.begin(), tpls.end(), [](const Tpl& x, const Tpl& y) { return x.dst < y.dst; });
        uint64_t bandMin[8]; for (auto& b : bandMin) b = ~0ull;
        uint32_t bandMaxTri[8] = {};
        std::vector<std::pair<uint64_t, size_t>> smallGaps;
        for (size_t k = 0; k + 1 < tpls.size(); ++k) {
            if (!tpls[k].dst || tpls[k + 1].dst == tpls[k].dst) continue;
            const uint64_t g = tpls[k + 1].dst - tpls[k].dst;
            const uint32_t band = std::min<uint32_t>(tpls[k].tri ? (tpls[k].tri - 1) / 16 : 0, 7);
            bandMin[band] = std::min(bandMin[band], g);
            bandMaxTri[band] = std::max(bandMaxTri[band], tpls[k].tri);
            smallGaps.push_back({ g, k });
        }
        std::partial_sort(smallGaps.begin(), smallGaps.begin() + std::min<size_t>(smallGaps.size(), 8), smallGaps.end());
        for (uint32_t b = 0; b < 8; ++b) {
            if (bandMin[b] != ~0ull) {
                Log("[Layout]   templates with %u..%u tri: min gap to next template=%llu", b * 16 + 1, b * 16 + 16,
                    static_cast<unsigned long long>(bandMin[b]));
            }
        }
        for (size_t s = 0; s < smallGaps.size() && s < 8; ++s) {
            const Tpl& t = tpls[smallGaps[s].second];
            Log("[Layout]   small gap %llu: template arg %u (tri=%u vtx=%u) at 0x%llx",
                static_cast<unsigned long long>(smallGaps[s].first), t.i, t.tri, t.vtx, static_cast<unsigned long long>(t.dst));
        }
    }
    // Extent of the template starting at sorted index k (gap to the next one, capped).
    auto tplExtent = [&](ptrdiff_t k) { return std::min<uint64_t>(tplAddrs->gap(static_cast<size_t>(k)), 16384); };

    // --- Instances -------------------------------------------------------------------------
    std::unique_ptr<SortedAddrs> clasAddrs;
    if (ic) {
        const uint32_t n = count(*ic);
        std::vector<uint64_t> dsts, refs;
        uint32_t nullTpl = 0, exact = 0, inside = 0, outside = 0, vbNot4 = 0, vbNot8 = 0, shown = 0;
        uint64_t vbLo = ~0ull, vbHi = 0;
        for (uint32_t i = 0; i < n; ++i) {
            const uint64_t o = ic->argOff + static_cast<uint64_t>(i) * ic->argStride;
            const uint64_t tp = U64(o + 8), vb = U64(o + 16);
            dsts.push_back(U64(ic->dstOff + static_cast<uint64_t>(i) * ic->dstStride));
            refs.push_back(tp);
            if (vb) { vbLo = std::min(vbLo, vb); vbHi = std::max(vbHi, vb); }
            if (vb & 3) ++vbNot4;
            if (vb & 7) ++vbNot8;
            if (!tp) { ++nullTpl; continue; }
            if (!tplAddrs) continue;
            const ptrdiff_t k = tplAddrs->floor(tp);
            if (k >= 0 && tplAddrs->a[k] == tp) { ++exact; continue; }
            const bool in = k >= 0 && tp - tplAddrs->a[k] < tplExtent(k);
            in ? ++inside : ++outside;
            if (shown < 8) {
                ++shown;
                Log("[Layout]   instance %u: template 0x%llx is NOT a built template (%s 0x%llx, +0x%llx)", i,
                    static_cast<unsigned long long>(tp), in ? "inside template at" : "nearest template below",
                    static_cast<unsigned long long>(k >= 0 ? tplAddrs->a[k] : 0),
                    static_cast<unsigned long long>(k >= 0 ? tp - tplAddrs->a[k] : 0));
            }
        }
        SortedAddrs distinctRefs(refs);
        Log("[Layout] instances: %u args, %zu distinct templates referenced | template ptr: exact=%u inside-another=%u "
            "outside=%u null=%u | vb [0x%llx..0x%llx] not 4-aligned=%u not 8-aligned=%u",
            n, distinctRefs.a.size(), exact, inside, outside, nullTpl,
            static_cast<unsigned long long>(vbLo == ~0ull ? 0 : vbLo), static_cast<unsigned long long>(vbHi), vbNot4, vbNot8);
        clasAddrs = std::make_unique<SortedAddrs>(dsts);
        LogGaps("CLAS dst", *clasAddrs);
        if (tplAddrs) {
            // Instantiated CLAS whose destination starts inside a template, or that leave less
            // than 4 KB (RDNA 4 writes ~4 KB for a 64-triangle CLAS) before the next template.
            uint32_t startsInTpl = 0, nearTpl = 0, shownOv = 0;
            for (size_t c = 0; c < clasAddrs->a.size(); ++c) {
                const uint64_t d = clasAddrs->a[c];
                const ptrdiff_t k = tplAddrs->floor(d);
                const bool in = k >= 0 && d - tplAddrs->a[k] < tplExtent(k);
                const ptrdiff_t nx = tplAddrs->ceil(d + 1);
                const uint64_t room = std::min<uint64_t>(clasAddrs->gap(c), 4096);
                const bool closeNext = nx >= 0 && tplAddrs->a[nx] - d < room;
                if (in) ++startsInTpl;
                if (closeNext) ++nearTpl;
                if ((in || closeNext) && shownOv < 8) {
                    ++shownOv;
                    Log("[Layout]   CLAS dst 0x%llx %s template 0x%llx", static_cast<unsigned long long>(d),
                        in ? "starts inside" : "runs into",
                        static_cast<unsigned long long>(in ? tplAddrs->a[k] : tplAddrs->a[nx]));
                }
            }
            Log("[Layout] CLAS vs templates: start inside a template=%u, next template closer than the CLAS=%u",
                startsInTpl, nearTpl);
        }
    }

    // --- BLAS ------------------------------------------------------------------------------
    if (bc) {
        const uint32_t n = count(*bc);
        std::vector<uint64_t> dsts;
        uint64_t sum = 0, arrLo = ~0ull, arrHi = 0;
        for (uint32_t i = 0; i < n; ++i) {
            const uint64_t o = bc->argOff + static_cast<uint64_t>(i) * bc->argStride;
            sum += U32(o);
            const uint64_t arr = U64(o + 8);
            if (arr) { arrLo = std::min(arrLo, arr); arrHi = std::max(arrHi, arr); }
            dsts.push_back(U64(bc->dstOff + static_cast<uint64_t>(i) * bc->dstStride));
        }
        SortedAddrs b(dsts);
        Log("[Layout] BLAS: %u args, %llu CLAS references, CLAS arrays [0x%llx..0x%llx]", n,
            static_cast<unsigned long long>(sum), static_cast<unsigned long long>(arrLo == ~0ull ? 0 : arrLo),
            static_cast<unsigned long long>(arrHi));
        LogGaps("BLAS dst", b);
        uint32_t inTpl = 0, inClas = 0;
        for (uint64_t d : b.a) {
            if (tplAddrs) { const ptrdiff_t k = tplAddrs->floor(d); if (k >= 0 && d - tplAddrs->a[k] < tplExtent(k)) ++inTpl; }
            if (clasAddrs) {
                const ptrdiff_t k = clasAddrs->floor(d);
                if (k >= 0 && d - clasAddrs->a[k] < std::min<uint64_t>(clasAddrs->gap(static_cast<size_t>(k)), 16384)) ++inClas;
            }
        }
        Log("[Layout] BLAS dst inside a template=%u, inside a CLAS=%u", inTpl, inClas);

        // CLAS addresses the BLAS actually read (instantiate destination array copied right
        // before the BLAS) vs the CLAS the instantiate built.
        if (bc->extraBytes) {
            uint32_t refs = 0, outsideArr = 0, valid = 0, notClas = 0, changed = 0, nulls = 0, shownC = 0;
            const uint32_t nInst = ic ? count(*ic) : 0;
            for (uint32_t i = 0; i < n; ++i) {
                const uint64_t o = bc->argOff + static_cast<uint64_t>(i) * bc->argStride;
                const uint32_t cnt = U32(o);
                const uint64_t arr = U64(o + 8);
                if (arr < bc->extraVa || arr + static_cast<uint64_t>(cnt) * 8u > bc->extraVa + bc->extraBytes ||
                    ((arr - bc->extraVa) & 7)) {
                    ++outsideArr;
                    continue;
                }
                const uint64_t first = (arr - bc->extraVa) / 8u;
                for (uint32_t j = 0; j < cnt; ++j) {
                    ++refs;
                    const uint64_t a = U64(bc->extraOff + (first + j) * 8u);
                    const ptrdiff_t ck = clasAddrs && a ? clasAddrs->floor(a) : -1;
                    const bool isClas = ck >= 0 && clasAddrs->a[static_cast<size_t>(ck)] == a;
                    const bool same = ic && ic->dstStride == 8 && first + j < nInst && U64(ic->dstOff + (first + j) * 8u) == a;
                    if (!a) ++nulls; else if (isClas) ++valid; else ++notClas;
                    if (ic && !same) ++changed;
                    if ((!isClas || (ic && !same)) && shownC < 8) {
                        ++shownC;
                        Log("[Layout]   BLAS %u ref %u (array idx %llu): 0x%llx %s%s", i, j, static_cast<unsigned long long>(first + j),
                            static_cast<unsigned long long>(a), isClas ? "is a CLAS" : "is NOT a built CLAS",
                            (ic && !same) ? ", differs from the instantiate destination at that index" : "");
                    }
                }
            }
            Log("[Layout] BLAS CLAS refs read at BLAS time: %u refs, valid CLAS=%u, not a CLAS=%u, null=%u, "
                "changed since the instantiate=%u, BLAS arrays outside the instantiate array=%u",
                refs, valid, notClas, nulls, changed, outsideArr);
        } else {
            Log("[Layout] BLAS CLAS refs: instantiate destination array not captured");
        }

        // Room each BLAS gets before the next object (CLAS or BLAS) vs the size reported for its CLAS count.
        std::map<uint32_t, uint64_t> sizes;
        { std::lock_guard<std::mutex> g(g_blasSizeMutex); sizes = g_reportedBlasSizes; }
        std::vector<uint64_t> objs = b.a;
        if (clasAddrs) objs.insert(objs.end(), clasAddrs->a.begin(), clasAddrs->a.end());
        std::sort(objs.begin(), objs.end());
        uint32_t tooSmall = 0, unknown = 0, shownB = 0;
        int64_t worst = INT64_MAX;
        for (uint32_t i = 0; i < n; ++i) {
            const uint64_t o = bc->argOff + static_cast<uint64_t>(i) * bc->argStride;
            const uint32_t cnt = U32(o);
            const uint64_t d = U64(bc->dstOff + static_cast<uint64_t>(i) * bc->dstStride);
            if (!d) continue;
            auto it = std::upper_bound(objs.begin(), objs.end(), d);
            const uint64_t room = it == objs.end() ? ~0ull : *it - d;
            auto sz = sizes.lower_bound(cnt);
            if (sz == sizes.end()) { ++unknown; continue; }
            const int64_t slack = static_cast<int64_t>(std::min<uint64_t>(room, 1ull << 40)) - static_cast<int64_t>(sz->second);
            worst = std::min(worst, slack);
            if (slack < 0) {
                ++tooSmall;
                if (shownB < 8) {
                    ++shownB;
                    Log("[Layout]   BLAS %u: %u CLAS at 0x%llx, room=%llu < reported %llu (for %u CLAS)", i, cnt,
                        static_cast<unsigned long long>(d), static_cast<unsigned long long>(room),
                        static_cast<unsigned long long>(sz->second), sz->first);
                }
            }
        }
        Log("[Layout] BLAS room vs reported size: too small=%u, size unknown=%u, min slack=%lld bytes (%zu sizes reported)",
            tooSmall, unknown, static_cast<long long>(worst == INT64_MAX ? 0 : worst), sizes.size());
    }

    // --- Split execution progress: arguments of the chunk that was running ---------------
    if (ctx.progress) {
        const uint32_t started = ctx.progress[0], completed = ctx.progress[1];
        Log("[Split] last chunk started: op %u chunk %d | last chunk completed: op %u chunk %d",
            started >> 16, static_cast<int>(started & 0xFFFFu) - 1, completed >> 16, static_cast<int>(completed & 0xFFFFu) - 1);
        const DeviceConverterContext::Capture* fc = nullptr;
        for (const auto& c : ctx.captures) {
            if (started && c.convOp == (started >> 16) && c.chunkSize) fc = &c;
        }
        if (force && started && started != completed && fc) {
            const uint32_t chunk = (started & 0xFFFFu) - 1;
            const uint32_t first = chunk * fc->chunkSize;
            const uint32_t last  = std::min(count(*fc), first + fc->chunkSize);
            Log("[Split] chunk in flight: type=%u args [%u..%u)", fc->type, first, last);
            auto findTpl = [&](uint64_t addr) -> const Tpl* {
                auto it = std::lower_bound(tpls.begin(), tpls.end(), addr,
                                           [](const Tpl& t, uint64_t a) { return t.dst < a; });
                return (it != tpls.end() && it->dst == addr) ? &*it : nullptr;
            };
            auto tplText = [&](const Tpl& t, char* buf, size_t n) {
                std::snprintf(buf, n, "targ=%u id=%u fl=0x%x tri=%u vtx=%u trunc=%u ifmt=%u geom=0x%x istr=%u vstr=%u ib=0x%llx hint=0x%llx",
                    t.i, t.id, t.flags, t.tri, t.vtx, (t.packed >> 18) & 0x3Fu, (t.packed >> 24) & 0xFu, t.geom,
                    t.strides & 0xFFFFu, t.strides >> 16, static_cast<unsigned long long>(t.ib),
                    static_cast<unsigned long long>(t.vb));
            };
            // BLAS that completed right before the one in flight: CLAS count and distinct
            // template geometry index/flags, to compare with the failing one.
            if (fc->type == kTypeBlasFromClas && fc->extraBytes && ic) {
                const uint32_t nInst = count(*ic);
                for (uint32_t b = first > 16 ? first - 16 : 0; b < first; ++b) {
                    const uint64_t o = fc->argOff + static_cast<uint64_t>(b) * fc->argStride;
                    const uint32_t cnt = U32(o);
                    const uint64_t arr = U64(o + 8);
                    if (arr < fc->extraVa || ((arr - fc->extraVa) & 7)) continue;
                    const uint64_t firstRef = (arr - fc->extraVa) / 8u;
                    uint32_t geoms[6] = {}, nGeoms = 0, maxTri = 0, maxVtx = 0, unknown = 0;
                    for (uint32_t j = 0; j < cnt; ++j) {
                        const uint64_t k = firstRef + j;
                        if (k >= nInst || ic->dstStride != 8) { ++unknown; continue; }
                        const uint64_t io = ic->argOff + k * ic->argStride;
                        const Tpl* tq = findTpl(U64(io + 8));
                        if (!tq) { ++unknown; continue; }
                        maxTri = std::max(maxTri, tq->tri);
                        maxVtx = std::max(maxVtx, tq->vtx);
                        bool seen = false;
                        for (uint32_t g = 0; g < nGeoms; ++g) seen |= geoms[g] == tq->geom;
                        if (!seen && nGeoms < 6) geoms[nGeoms++] = tq->geom;
                    }
                    char gtxt[96] = "";
                    size_t pos = 0;
                    for (uint32_t g = 0; g < nGeoms && pos < sizeof(gtxt); ++g) {
                        pos += std::snprintf(gtxt + pos, sizeof(gtxt) - pos, "%s0x%x", g ? "," : "", geoms[g]);
                    }
                    Log("[Split]   done blas %u: clasCount=%u geom={%s} maxTri=%u maxVtx=%u unknown=%u", b, cnt, gtxt,
                        maxTri, maxVtx, unknown);
                }
            }
            for (uint32_t i = first; i < last; ++i) {
                const uint64_t o = fc->argOff + static_cast<uint64_t>(i) * fc->argStride;
                const uint64_t dst = U64(fc->dstOff + static_cast<uint64_t>(i) * fc->dstStride);
                char t[256] = "template not found";
                if (fc->type == kTypeInstantiate) {
                    const uint64_t tp = U64(o + 8);
                    if (const Tpl* tt = findTpl(tp)) tplText(*tt, t, sizeof(t));
                    Log("[Split]   inst %u: cid+=%u geom+=%u tpl=0x%llx vb=0x%llx vs=%llu dst=0x%llx | %s", i, U32(o), U32(o + 4),
                        static_cast<unsigned long long>(tp), static_cast<unsigned long long>(U64(o + 16)),
                        static_cast<unsigned long long>(U64(o + 24)), static_cast<unsigned long long>(dst), t);
                } else if (fc->type == kTypeTemplates) {
                    if (const Tpl* tt = findTpl(dst)) tplText(*tt, t, sizeof(t));
                    Log("[Split]   tpl %u: dst=0x%llx | %s", i, static_cast<unsigned long long>(dst), t);
                } else if (fc->type == kTypeBlasFromClas) {
                    const uint32_t cnt = U32(o);
                    const uint64_t arr = U64(o + 8);
                    Log("[Split]   blas %u: clasCount=%u reserved=%u clasArray=0x%llx dst=0x%llx", i, cnt, U32(o + 4),
                        static_cast<unsigned long long>(arr), static_cast<unsigned long long>(dst));
                    if (fc->extraBytes && arr >= fc->extraVa && !((arr - fc->extraVa) & 7) &&
                        arr + static_cast<uint64_t>(cnt) * 8u <= fc->extraVa + fc->extraBytes) {
                        const uint64_t firstRef = (arr - fc->extraVa) / 8u;
                        const uint32_t nInst = ic ? count(*ic) : 0;
                        for (uint32_t j = 0; j < cnt && j < 64; ++j) {
                            const uint64_t a = U64(fc->extraOff + (firstRef + j) * 8u);
                            // Instance that built this CLAS (same destination index, else search).
                            int64_t inst = -1;
                            if (ic && firstRef + j < nInst && U64(ic->dstOff + (firstRef + j) * ic->dstStride) == a) {
                                inst = static_cast<int64_t>(firstRef + j);
                            } else if (ic) {
                                for (uint32_t k = 0; k < nInst; ++k) {
                                    if (U64(ic->dstOff + static_cast<uint64_t>(k) * ic->dstStride) == a) { inst = k; break; }
                                }
                            }
                            char tt[320] = "no instance built this address";
                            if (inst >= 0) {
                                const uint64_t io = ic->argOff + static_cast<uint64_t>(inst) * ic->argStride;
                                const uint64_t tp = U64(io + 8);
                                char tx[256] = "template not found";
                                if (const Tpl* tq = findTpl(tp)) tplText(*tq, tx, sizeof(tx));
                                std::snprintf(tt, sizeof(tt), "inst %lld cid+=%u geom+=%u vb=0x%llx | %s", static_cast<long long>(inst),
                                              U32(io), U32(io + 4), static_cast<unsigned long long>(U64(io + 16)), tx);
                            }
                            const ptrdiff_t ck = clasAddrs && a ? clasAddrs->floor(a) : -1;
                            const uint64_t room = (ck >= 0 && clasAddrs->a[static_cast<size_t>(ck)] == a)
                                ? clasAddrs->gap(static_cast<size_t>(ck)) : 0;
                            Log("[Split]     clas %u: 0x%llx room=%llu | %s", j, static_cast<unsigned long long>(a),
                                static_cast<unsigned long long>(room == ~0ull ? 0 : room), tt);
                        }
                    }
                }
            }
        }
    }
    Log("[Layout] ===== end =====");
    WriteRealCapture(ctx);
}

// AMD_MG_SPLIT_OPS=N: explicit-destination CLAS / template / instantiate operations with more
// than N arguments are executed as chunks of N (default 256, 0 = off), with GPU progress markers
// so a device removal names the chunk in flight.
uint32_t SplitChunkSize() {
    static const uint32_t k = [] {
        char value[16] = {};
        const DWORD len = GetEnvironmentVariableA("AMD_MG_SPLIT_OPS", value, sizeof(value));
        uint32_t v = 256;
        if (len > 0 && len < sizeof(value)) v = static_cast<uint32_t>(std::strtoul(value, nullptr, 10));
        v = std::min<uint32_t>(v, 0xFFFFu);
        Log("[Converter] Split execution: %s (AMD_MG_SPLIT_OPS)", v ? "on" : "off");
        if (v) Log("[Converter]   %u arguments per chunk", v);
        return v;
    }();
    return k;
}

// AMD_MG_SPLIT_BLAS=N: BUILD_BLAS_FROM_CLAS operations are executed as chunks of N BLAS
// (default 1, 0 = off). AW2 builds 499 BLAS of 2..4458 CLAS in one operation; one BLAS per
// operation keeps maxArgCount x maxClasPerArg at the size of a single BLAS and names the BLAS
// in flight at a device removal.
uint32_t SplitBlasChunkSize() {
    static const uint32_t k = [] {
        char value[16] = {};
        const DWORD len = GetEnvironmentVariableA("AMD_MG_SPLIT_BLAS", value, sizeof(value));
        uint32_t v = 1;
        if (len > 0 && len < sizeof(value)) v = static_cast<uint32_t>(std::strtoul(value, nullptr, 10));
        v = std::min<uint32_t>(v, 0xFFFFu);
        Log("[Converter] BLAS split execution: %s (AMD_MG_SPLIT_BLAS)", v ? "on" : "off");
        if (v) Log("[Converter]   %u BLAS per chunk", v);
        return v;
    }();
    return k;
}

bool EnvFlagOnce(const char* name, const char* what) {
    char value[16] = {};
    const DWORD len = GetEnvironmentVariableA(name, value, sizeof(value));
    const bool on = len > 0 && len < sizeof(value) && std::atoi(value) != 0;
    if (on) Log("[A/B] %s=1: %s", name, what);
    return on;
}

} // namespace

bool BlasPrivateScratchEnabled() {
    static const bool on = EnvFlagOnce("AMD_MG_BLAS_PRIVATE_SCRATCH", "BLAS operations use a wrapper-owned scratch buffer");
    return on;
}

bool ForceGeom0Enabled() {
    static const bool on = EnvFlagOnce("AMD_MG_FORCE_GEOM0", "CLAS / template geometry index forced to 0 (flags kept)");
    return on;
}

bool TemplateNoHintEnabled() {
    static const bool on = EnvFlagOnce("AMD_MG_TEMPLATE_NO_HINT", "templates built without the hint vertex buffer");
    return on;
}

bool BlasFakeClasEnabled() {
    static const bool on = EnvFlagOnce("AMD_MG_BLAS_FAKE_CLAS", "every BLAS is built from one wrapper-built one-triangle CLAS");
    return on;
}

D3D12_GPU_VIRTUAL_ADDRESS AcquireBlasPrivateScratch(ID3D12Device* dev, uint64_t bytes) {
    static std::mutex s_mutex;
    static std::map<ID3D12Device*, std::vector<ComPtr<ID3D12Resource>>> s_buffers; // old ones kept alive
    std::lock_guard<std::mutex> lock(s_mutex);
    auto& list = s_buffers[dev];
    if (!list.empty() && list.back()->GetDesc().Width >= bytes) {
        return list.back()->GetGPUVirtualAddress();
    }
    uint64_t size = AlignUp(std::max<uint64_t>(bytes, list.empty() ? 0 : list.back()->GetDesc().Width * 2), 65536);
    D3D12_RESOURCE_DESC d{};
    d.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
    d.Width = size;
    d.Height = 1; d.DepthOrArraySize = 1; d.MipLevels = 1; d.SampleDesc.Count = 1;
    d.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    d.Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
    D3D12_HEAP_PROPERTIES hp{};
    hp.Type = D3D12_HEAP_TYPE_DEFAULT;
    ComPtr<ID3D12Resource> buf;
    if (FAILED(dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d, D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
                                            nullptr, IID_PPV_ARGS(&buf)))) {
        Log("[A/B] private BLAS scratch: allocation of %llu bytes failed", static_cast<unsigned long long>(size));
        return 0;
    }
    Log("[A/B] private BLAS scratch: %llu bytes at [0x%llx..0x%llx) (requested %llu)", static_cast<unsigned long long>(size),
        static_cast<unsigned long long>(buf->GetGPUVirtualAddress()),
        static_cast<unsigned long long>(buf->GetGPUVirtualAddress() + size), static_cast<unsigned long long>(bytes));
    list.push_back(buf);
    return buf->GetGPUVirtualAddress();
}

namespace {

// AMD_MG_BLAS_FAKE_CLAS: builds (once per device, on the game's command list, before its first
// BLAS operation) a one-triangle CLAS and returns the GPU address of a one-entry CLAS address
// array pointing at it, or 0.
D3D12_GPU_VIRTUAL_ADDRESS EnsureFakeClas(ID3D12GraphicsCommandList* cl, ID3D12Device* dev, DeviceConverterContext& ctx) {
    if (ctx.fakeBuilt) return ctx.fakeArrVa;
    if (ctx.fakeTried) return 0;
    ctx.fakeTried = true;
    ComPtr<ID3D12DeviceRaytracing2> rt2;
    ComPtr<ID3D12CommandListRaytracing2> cl2;
    if (FAILED(dev->QueryInterface(IID_PPV_ARGS(&rt2))) || !rt2 || FAILED(cl->QueryInterface(IID_PPV_ARGS(&cl2))) || !cl2) {
        Log("[A/B] fake CLAS: raytracing 2 interfaces not available");
        return 0;
    }
    // DXR inputs built directly (the NvAPI translation lives in nvapi_proxy.cpp, not linked
    // into every binary). Own operation: 16-bit indices whatever AMD_MG_INDEX_FORMAT says.
    TranslatedClusterInputs t{};
    auto& lim = t.trianglesDesc.ClusterLimits;
    lim.MaxArgCount                                   = 1;
    lim.MaxGeometryIndexValue                         = 0;
    lim.MaxUniqueGeometryIndexAndFlagsCountPerCluster = 1;
    lim.MaxTriangleCountPerCluster                    = 1;
    lim.MaxUniqueVertexIndexCountPerCluster           = 3;
    lim.MaxTotalTriangleCount                         = 1;
    lim.MaxSumOfUniqueVertexIndexCounts               = 3;
    lim.MaxOpacityMicromapIndicesPerCluster           = 0;
    t.trianglesDesc.Flags                            = D3D12_RTAS_OPERATION_FLAG_ALLOW_DATA_ACCESS;
    t.trianglesDesc.Mode                             = static_cast<D3D12_RTAS_OPERATION_MODE>(
        NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_MODE_EXPLICIT_DESTINATIONS);
    t.trianglesDesc.VertexFormat                     = D3D12_VERTEX_FORMAT_FLOAT32_3;
    t.trianglesDesc.IndexFormat                      = D3D12_INDEX_FORMAT_UINT16;
    t.trianglesDesc.GeometryIndexAndFlagsIndexFormat = D3D12_INDEX_FORMAT_NONE;
    t.trianglesDesc.OpacityMicromapIndexFormat       = D3D12_INDEX_FORMAT_NONE;
    t.trianglesDesc.MinPositionTruncateBitCount      = 0;
    t.inputs.Type                  = D3D12_RTAS_OPERATION_TYPE_BUILD_CLAS_FROM_TRIANGLES;
    t.inputs.pClusterTrianglesDesc = &t.trianglesDesc;
    D3D12_RTAS_OPERATION_PREBUILD_INFO info{};
    rt2->GetRTASOperationPrebuildInfo(&t.inputs, &info);
    if (info.ResultDataMaxSizeInBytes == 0) {
        Log("[A/B] fake CLAS: prebuild info rejected");
        return 0;
    }
    auto make = [&](D3D12_HEAP_TYPE heap, uint64_t size, D3D12_RESOURCE_STATES state, D3D12_RESOURCE_FLAGS flags,
                    ComPtr<ID3D12Resource>& out) {
        D3D12_RESOURCE_DESC d{};
        d.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
        d.Width = AlignUp(std::max<uint64_t>(size, 256), 256);
        d.Height = 1; d.DepthOrArraySize = 1; d.MipLevels = 1; d.SampleDesc.Count = 1;
        d.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
        d.Flags = flags;
        D3D12_HEAP_PROPERTIES hp{};
        hp.Type = heap;
        return SUCCEEDED(dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d, state, nullptr, IID_PPV_ARGS(&out)));
    };
    if (!make(D3D12_HEAP_TYPE_UPLOAD, 4096, D3D12_RESOURCE_STATE_GENERIC_READ, D3D12_RESOURCE_FLAG_NONE, ctx.fakeIn) ||
        !make(D3D12_HEAP_TYPE_DEFAULT, info.ResultDataMaxSizeInBytes, D3D12_RESOURCE_STATE_RAYTRACING_ACCELERATION_STRUCTURE,
              D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS | D3D12_RESOURCE_FLAG_RAYTRACING_ACCELERATION_STRUCTURE, ctx.fakeClas) ||
        !make(D3D12_HEAP_TYPE_DEFAULT, info.ScratchDataSizeInBytes, D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
              D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS, ctx.fakeScratch)) {
        Log("[A/B] fake CLAS: buffer allocation failed");
        return 0;
    }
    const D3D12_GPU_VIRTUAL_ADDRESS in = ctx.fakeIn->GetGPUVirtualAddress();
    const D3D12_GPU_VIRTUAL_ADDRESS clas = ctx.fakeClas->GetGPUVirtualAddress();
    constexpr uint64_t kVb = 0, kIb = 64, kArgs = 256, kDst = 512, kArr = 576;
    uint8_t* p = nullptr;
    if (FAILED(ctx.fakeIn->Map(0, nullptr, reinterpret_cast<void**>(&p))) || !p) return 0;
    std::memset(p, 0, 4096);
    const float vtx[9] = { 0.f, 0.f, 0.f, 0.001f, 0.f, 0.f, 0.f, 0.001f, 0.f };
    std::memcpy(p + kVb, vtx, sizeof(vtx));
    const uint16_t idx[3] = { 0, 1, 2 };
    std::memcpy(p + kIb, idx, sizeof(idx));
    D3D12_RTAS_OPERATION_BUILD_CLAS_FROM_TRIANGLES_ARGS a{};
    a.ClusterID = 0;
    a.TriangleCount = 1;
    a.UniqueVertexIndexCount = 3;
    a.BaseGeometryIndexAndFlags = 0x80000000u; // geometry 0, opaque
    a.VertexBufferStride = 12;
    a.IndexBufferStride = 2;
    a.VertexBuffer = in + kVb;
    a.IndexBuffer  = in + kIb;
    std::memcpy(p + kArgs, &a, sizeof(a));
    std::memcpy(p + kDst, &clas, 8);
    std::memcpy(p + kArr, &clas, 8);
    ctx.fakeIn->Unmap(0, nullptr);

    D3D12_RTAS_BATCHED_OPERATION_DATA data{};
    data.BatchScratchData                    = ctx.fakeScratch->GetGPUVirtualAddress();
    data.ResultAddressArray.StartAddress     = in + kDst;
    data.ResultAddressArray.StrideInBytes    = 8;
    data.IndirectArgumentArray.StartAddress  = in + kArgs;
    data.IndirectArgumentArray.StrideInBytes = sizeof(a);
    data.IndirectArgumentArraySize           = 0;
    D3D12_RTAS_OPERATION_DESC op{};
    op.Inputs = t.inputs;
    op.pBatchedOperationData = &data;
    cl2->ExecuteIndirectRTASOperations(1, &op, D3D12_EXECUTE_INDIRECT_RTAS_OPERATIONS_FLAG_NONE);
    GlobalUavBarrier(cl);
    ctx.fakeBuilt = true;
    ctx.fakeArrVa = in + kArr;
    Log("[A/B] fake CLAS: 1 triangle, %llu bytes at 0x%llx, address array at 0x%llx",
        static_cast<unsigned long long>(info.ResultDataMaxSizeInBytes), static_cast<unsigned long long>(clas),
        static_cast<unsigned long long>(ctx.fakeArrVa));
    return ctx.fakeArrVa;
}

// AMD_MG_CAPTURE_REAL=N (N BLAS, default 0 = off): at the first BLAS operation, copies on the GPU
// (ExecuteIndirect with per-command root SRV/UAV, addresses chased by modes 13/14 of the
// converter shader) the index data and vertex windows of every CLAS of the first N BLAS into a
// readback buffer, before the BLAS runs. AnalyseLayoutLocked writes them to
// amd_megageometry_capture.bin next to the DLL; tests\replay_capture rebuilds them offline.
uint32_t RealCaptureBlasCount() {
    static const uint32_t n = [] {
        char value[16] = {};
        const DWORD len = GetEnvironmentVariableA("AMD_MG_CAPTURE_REAL", value, sizeof(value));
        uint32_t v = 0;
        if (len > 0 && len < sizeof(value)) v = static_cast<uint32_t>(std::strtoul(value, nullptr, 10));
        v = std::min<uint32_t>(v, 64);
        if (v) Log("[Real] AMD_MG_CAPTURE_REAL=%u: real cluster data of the first %u BLAS will be captured", v, v);
        return v;
    }();
    return n;
}

constexpr uint32_t kRealMaxClas   = 8192;
constexpr uint64_t kRealDataCap   = 160ull << 20;
constexpr uint32_t kRealWindowCap = 1u << 20;
constexpr uint32_t kRealSentinel  = 0xCA9E0001u;

void RecordRealCapture(ID3D12GraphicsCommandList* cl, ID3D12Device* dev, DeviceConverterContext& ctx) {
    if (ctx.realRecorded || !ctx.capMapped) return;
    const uint32_t nBlas = RealCaptureBlasCount();
    if (!nBlas) return;
    const DeviceConverterContext::Capture *tc = nullptr, *ic = nullptr, *bc = nullptr;
    uint32_t tci = 0, ici = 0;
    for (uint32_t i = 0; i < ctx.captures.size(); ++i) {
        const auto& c = ctx.captures[i];
        if (c.type == kTypeTemplates) { tc = &c; tci = i; }
        if (c.type == kTypeInstantiate) { ic = &c; ici = i; }
        if (c.type == kTypeBlasFromClas) bc = &c;
    }
    if (!tc || !ic || !bc || bc->convOp != ctx.currentConvOp || !bc->extraBytes) {
        Log("[Real] capture skipped: layout captures missing (templates=%d instantiate=%d blas=%d)", tc ? 1 : 0, ic ? 1 : 0, bc ? 1 : 0);
        ctx.realRecorded = true;
        return;
    }
    ctx.realRecorded = true;
    const uint32_t M = kRealMaxClas;
    const uint64_t cmdAOff = 0, cmdBOff = uint64_t(M) * 64, recOff = uint64_t(M) * 192, rec2Off = uint64_t(M) * 256,
                   cntOff = uint64_t(M) * 320, planBytes = cntOff + 256;
    auto make = [&](D3D12_HEAP_TYPE heap, uint64_t size, D3D12_RESOURCE_STATES state, bool uav, ComPtr<ID3D12Resource>& out) {
        D3D12_RESOURCE_DESC rd{};
        rd.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
        rd.Width = size;
        rd.Height = 1; rd.DepthOrArraySize = 1; rd.MipLevels = 1; rd.SampleDesc.Count = 1;
        rd.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
        rd.Flags = uav ? D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS : D3D12_RESOURCE_FLAG_NONE;
        D3D12_HEAP_PROPERTIES hp{};
        hp.Type = heap;
        return SUCCEEDED(dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &rd, state, nullptr, IID_PPV_ARGS(&out)));
    };
    void* rbMapped = nullptr;
    if (!make(D3D12_HEAP_TYPE_DEFAULT, planBytes, D3D12_RESOURCE_STATE_UNORDERED_ACCESS, true, ctx.realPlan) ||
        !make(D3D12_HEAP_TYPE_DEFAULT, kRealDataCap, D3D12_RESOURCE_STATE_UNORDERED_ACCESS, true, ctx.realData) ||
        !make(D3D12_HEAP_TYPE_UPLOAD, 256, D3D12_RESOURCE_STATE_GENERIC_READ, false, ctx.realParams) ||
        !make(D3D12_HEAP_TYPE_READBACK, planBytes + kRealDataCap + 256, D3D12_RESOURCE_STATE_COPY_DEST, false, ctx.realRb) ||
        FAILED(ctx.realRb->Map(0, nullptr, &rbMapped))) {
        Log("[Real] capture skipped: buffer allocation failed");
        return;
    }
    std::memset(rbMapped, 0, 256); // plan head; the sentinel lives at the end
    reinterpret_cast<uint8_t*>(rbMapped)[planBytes + kRealDataCap] = 0;
    std::memset(reinterpret_cast<uint8_t*>(rbMapped) + planBytes + kRealDataCap, 0, 256);
    ctx.realRbMapped = static_cast<const uint8_t*>(rbMapped);

    // Order matters: the runtime rejects (E_INVALIDARG) root constants after root descriptors.
    // Layout per command: see WriteCopyCmd in arg_converter.hlsl.
    D3D12_INDIRECT_ARGUMENT_DESC args[4]{};
    args[0].Type = D3D12_INDIRECT_ARGUMENT_TYPE_CONSTANT;
    args[0].Constant.RootParameterIndex = 0;
    args[0].Constant.DestOffsetIn32BitValues = 0;
    args[0].Constant.Num32BitValuesToSet = 7;
    args[1].Type = D3D12_INDIRECT_ARGUMENT_TYPE_SHADER_RESOURCE_VIEW;
    args[1].ShaderResourceView.RootParameterIndex = 1;
    args[2].Type = D3D12_INDIRECT_ARGUMENT_TYPE_UNORDERED_ACCESS_VIEW;
    args[2].UnorderedAccessView.RootParameterIndex = 2;
    args[3].Type = D3D12_INDIRECT_ARGUMENT_TYPE_DISPATCH;
    D3D12_COMMAND_SIGNATURE_DESC sd{};
    sd.ByteStride = 64;
    sd.NumArgumentDescs = 4;
    sd.pArgumentDescs = args;
    const HRESULT hrSig = dev->CreateCommandSignature(&sd, ctx.rootSig.Get(), IID_PPV_ARGS(&ctx.realSig));
    if (FAILED(hrSig)) {
        Log("[Real] capture skipped: CreateCommandSignature hr=0x%08x", static_cast<unsigned>(hrSig));
        return;
    }

    const D3D12_GPU_VIRTUAL_ADDRESS planVa = ctx.realPlan->GetGPUVirtualAddress();
    const D3D12_GPU_VIRTUAL_ADDRESS dataVa = ctx.realData->GetGPUVirtualAddress();
    const D3D12_GPU_VIRTUAL_ADDRESS parVa  = ctx.realParams->GetGPUVirtualAddress();
    uint32_t P[32] = {};
    P[0] = nBlas;  P[1] = M;
    P[2] = static_cast<uint32_t>(bc->argOff);  P[3] = bc->argStride;
    P[4] = bc->hasCount ? static_cast<uint32_t>(bc->countOff) : 0xFFFFFFFFu;  P[5] = bc->argCount;
    P[6] = static_cast<uint32_t>(bc->extraOff);
    P[7] = static_cast<uint32_t>(bc->extraVa);  P[8] = static_cast<uint32_t>(bc->extraVa >> 32);
    P[9] = static_cast<uint32_t>(bc->extraBytes);
    P[10] = static_cast<uint32_t>(tc->argOff);  P[11] = tc->argStride;
    P[12] = static_cast<uint32_t>(tc->dstOff);  P[13] = tc->dstStride;  P[14] = tc->argCount;
    P[16] = static_cast<uint32_t>(ic->argOff);  P[17] = ic->argStride;  P[18] = ic->argCount;
    P[19] = ic->hasCount ? static_cast<uint32_t>(ic->countOff) : 0xFFFFFFFFu;
    P[20] = static_cast<uint32_t>(dataVa);  P[21] = static_cast<uint32_t>(dataVa >> 32);
    P[22] = static_cast<uint32_t>(kRealDataCap);
    P[23] = static_cast<uint32_t>(cmdAOff);  P[24] = static_cast<uint32_t>(cmdBOff);  P[25] = static_cast<uint32_t>(recOff);
    P[26] = static_cast<uint32_t>(cntOff);  P[27] = kRealWindowCap;  P[28] = static_cast<uint32_t>(rec2Off);
    void* pp = nullptr;
    ctx.realParams->Map(0, nullptr, &pp);
    std::memcpy(pp, P, sizeof(P));
    ctx.realParams->Unmap(0, nullptr);

    GlobalUavBarrier(cl);
    cl->SetComputeRootSignature(ctx.rootSig.Get());
    cl->SetPipelineState(ctx.pso.Get());
    const uint32_t c13[7] = { M, 0, 0, 13, 0, 0, 0 };
    cl->SetComputeRoot32BitConstants(0, 7, c13, 0);
    cl->SetComputeRootShaderResourceView(1, ctx.capGpu->GetGPUVirtualAddress());
    cl->SetComputeRootUnorderedAccessView(2, planVa);
    cl->SetComputeRootShaderResourceView(3, parVa);
    cl->Dispatch((M + 63) / 64, 1, 1);
    GlobalUavBarrier(cl);
    Transition(cl, ctx.realPlan.Get(), D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_INDIRECT_ARGUMENT);
    cl->ExecuteIndirect(ctx.realSig.Get(), M, ctx.realPlan.Get(), cmdAOff, nullptr, 0);
    Transition(cl, ctx.realPlan.Get(), D3D12_RESOURCE_STATE_INDIRECT_ARGUMENT, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    GlobalUavBarrier(cl);
    Transition(cl, ctx.realData.Get(), D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    const uint32_t c14[7] = { M, 0, 0, 14, 0, 0, 0 };
    cl->SetComputeRootSignature(ctx.rootSig.Get());
    cl->SetPipelineState(ctx.pso.Get());
    cl->SetComputeRoot32BitConstants(0, 7, c14, 0);
    cl->SetComputeRootShaderResourceView(1, dataVa);
    cl->SetComputeRootUnorderedAccessView(2, planVa);
    cl->SetComputeRootShaderResourceView(3, parVa);
    cl->Dispatch((M + 63) / 64, 1, 1);
    GlobalUavBarrier(cl);
    Transition(cl, ctx.realData.Get(), D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    Transition(cl, ctx.realPlan.Get(), D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_INDIRECT_ARGUMENT);
    cl->ExecuteIndirect(ctx.realSig.Get(), 2 * M, ctx.realPlan.Get(), cmdBOff, nullptr, 0);
    GlobalUavBarrier(cl);
    Transition(cl, ctx.realPlan.Get(), D3D12_RESOURCE_STATE_INDIRECT_ARGUMENT, D3D12_RESOURCE_STATE_COPY_SOURCE);
    Transition(cl, ctx.realData.Get(), D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    cl->CopyBufferRegion(ctx.realRb.Get(), 0, ctx.realPlan.Get(), 0, planBytes);
    cl->CopyBufferRegion(ctx.realRb.Get(), planBytes, ctx.realData.Get(), 0, kRealDataCap);
    Transition(cl, ctx.realPlan.Get(), D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    Transition(cl, ctx.realData.Get(), D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    ComPtr<ID3D12GraphicsCommandList2> l2;
    if (SUCCEEDED(cl->QueryInterface(IID_PPV_ARGS(&l2))) && l2) {
        D3D12_WRITEBUFFERIMMEDIATE_PARAMETER prm{};
        prm.Dest  = ctx.realRb->GetGPUVirtualAddress() + planBytes + kRealDataCap;
        prm.Value = kRealSentinel;
        D3D12_WRITEBUFFERIMMEDIATE_MODE m = D3D12_WRITEBUFFERIMMEDIATE_MODE_MARKER_OUT;
        l2->WriteBufferImmediate(1, &prm, &m);
    }
    ctx.realM = M;
    ctx.realN = nBlas;
    ctx.realTc = tci;
    ctx.realIc = ici;
    ctx.realPlanBytes = planBytes;
    ctx.realDataCap = kRealDataCap;
    Log("[Real] capture recorded: first %u BLAS, up to %u CLAS, plan %llu bytes, data up to %llu bytes", nBlas, M,
        static_cast<unsigned long long>(planBytes), static_cast<unsigned long long>(kRealDataCap));
}

// Writes amd_megageometry_capture.bin (see tests\replay_capture.cpp for the format).
void WriteRealCapture(DeviceConverterContext& ctx) {
    if (!ctx.realRbMapped || ctx.realWritten || !ctx.realM) return;
    const uint8_t* rb = ctx.realRbMapped;
    uint32_t sentinel = 0;
    std::memcpy(&sentinel, rb + ctx.realPlanBytes + ctx.realDataCap, 4);
    if (sentinel != kRealSentinel) {
        Log("[Real] capture not written: the GPU did not finish the copy (sentinel 0x%08x)", sentinel);
        return;
    }
    ctx.realWritten = true;
    const uint32_t M = ctx.realM;
    const uint64_t recOff = uint64_t(M) * 192, rec2Off = uint64_t(M) * 256, cntOff = uint64_t(M) * 320;
    uint32_t dataBytes = 0;
    std::memcpy(&dataBytes, rb + cntOff, 4);
    dataBytes = static_cast<uint32_t>(std::min<uint64_t>(dataBytes, ctx.realDataCap));
    const auto& tc = ctx.captures[ctx.realTc];
    const auto& ic = ctx.captures[ctx.realIc];
    const uint8_t* cm = ctx.capMapped;

    char path[MAX_PATH] = {};
    HMODULE self = nullptr;
    GetModuleHandleExA(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                       reinterpret_cast<LPCSTR>(&WriteRealCapture), &self);
    std::string file = "amd_megageometry_capture.bin";
    if (self && GetModuleFileNameA(self, path, MAX_PATH) > 0) {
        if (char* slash = std::strrchr(path, '\\')) { slash[1] = 0; file = std::string(path) + file; }
    }
    FILE* f = nullptr;
    if (fopen_s(&f, file.c_str(), "wb") != 0 || !f) {
        Log("[Real] cannot write %s", file.c_str());
        return;
    }
    const uint32_t version = 1, recBytes = 64, inSize = sizeof(ctx.capInputs[0]);
    std::fwrite("AMGCAP01", 1, 8, f);
    std::fwrite(&version, 4, 1, f);
    std::fwrite(&M, 4, 1, f);
    std::fwrite(&ctx.realN, 4, 1, f);
    std::fwrite(&recBytes, 4, 1, f);
    std::fwrite(&inSize, 4, 1, f);
    std::fwrite(&ctx.capInputs[kTypeTemplates & 7u], inSize, 1, f);
    std::fwrite(&ctx.capInputs[kTypeInstantiate & 7u], inSize, 1, f);
    std::fwrite(&ctx.capInputs[kTypeBlasFromClas & 7u], inSize, 1, f);
    std::fwrite(&dataBytes, 4, 1, f);
    uint32_t valid = 0, withTpl = 0, withIb = 0, withVb = 0, withHint = 0, clamped = 0, overflow = 0;
    for (uint32_t s = 0; s < M; ++s) {
        const uint8_t* rec  = rb + recOff + uint64_t(s) * 64;
        const uint8_t* rec2 = rb + rec2Off + uint64_t(s) * 64;
        uint32_t r[16];
        std::memcpy(r, rec, 64);
        uint8_t inst[32] = {}, tpl[72] = {};
        if (r[0] & 1u) {
            ++valid;
            const uint32_t k = r[3], t = r[4];
            if (k < ic.argCount) std::memcpy(inst, cm + ic.argOff + uint64_t(k) * ic.argStride, std::min<uint32_t>(32, ic.argStride));
            if ((r[0] & 2u) && t < tc.argCount) {
                ++withTpl;
                std::memcpy(tpl, cm + tc.argOff + uint64_t(t) * tc.argStride, std::min<uint32_t>(72, tc.argStride));
            }
            if (r[0] & 4u) ++withIb;
            if (r[0] & 8u) ++withVb;
            if (r[0] & 16u) ++withHint;
            if (r[0] & 32u) ++clamped;
            if (r[0] & 64u) ++overflow;
        }
        std::fwrite(rec, 64, 1, f);
        std::fwrite(rec2, 64, 1, f);
        std::fwrite(inst, 32, 1, f);
        std::fwrite(tpl, 72, 1, f);
    }
    std::fwrite(rb + ctx.realPlanBytes, 1, dataBytes, f);
    std::fclose(f);
    Log("[Real] wrote %s: %u BLAS, %u CLAS (template %u, indices %u, vertices %u, hint %u, clamped windows %u, data overflow %u), %u data bytes",
        file.c_str(), ctx.realN, valid, withTpl, withIb, withVb, withHint, clamped, overflow, dataBytes);
}

bool EnsureProgressBuffer(ID3D12Device* dev, DeviceConverterContext& ctx) {
    if (ctx.progress) return true;
    if (ctx.progressTried) return false;
    ctx.progressTried = true;
    D3D12_RESOURCE_DESC d{};
    d.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
    d.Width = 256;
    d.Height = 1; d.DepthOrArraySize = 1; d.MipLevels = 1; d.SampleDesc.Count = 1;
    d.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    D3D12_HEAP_PROPERTIES hp{};
    hp.Type = D3D12_HEAP_TYPE_READBACK;
    void* mapped = nullptr;
    if (FAILED(dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d, D3D12_RESOURCE_STATE_COPY_DEST,
                                            nullptr, IID_PPV_ARGS(&ctx.progressRb))) ||
        FAILED(ctx.progressRb->Map(0, nullptr, &mapped))) {
        ctx.progressRb.Reset();
        return false;
    }
    std::memset(mapped, 0, 256);
    ctx.progress = static_cast<volatile uint32_t*>(mapped);
    return true;
}

} // namespace

void NoteReportedBlasSize(uint32_t clasCount, uint64_t resultBytes) {
    std::lock_guard<std::mutex> g(g_blasSizeMutex);
    uint64_t& v = g_reportedBlasSizes[clasCount];
    v = std::max(v, resultBytes);
}

void RecordChunkProgress(ID3D12GraphicsCommandList* pCmdList, const ConvertedGpuDispatch& dispatch,
                         uint32_t chunk, bool completed) {
    if (!pCmdList || !dispatch.chunkSize) return;
    ComPtr<ID3D12Device> pDevice;
    if (FAILED(pCmdList->GetDevice(IID_PPV_ARGS(&pDevice))) || !pDevice) return;
    std::lock_guard<std::mutex> lock(g_convMutex);
    auto it = g_deviceContexts.find(pDevice.Get());
    if (it == g_deviceContexts.end() || !it->second.progressRb) return;
    const DeviceConverterContext& ctx = it->second;
    const D3D12_COMMAND_LIST_TYPE type = pCmdList->GetType();
    if (!((type == D3D12_COMMAND_LIST_TYPE_DIRECT && ctx.wbiDirect) ||
          (type == D3D12_COMMAND_LIST_TYPE_COMPUTE && ctx.wbiCompute))) return;
    ComPtr<ID3D12GraphicsCommandList2> l2;
    if (FAILED(pCmdList->QueryInterface(IID_PPV_ARGS(&l2))) || !l2) return;
    D3D12_WRITEBUFFERIMMEDIATE_PARAMETER prm{};
    prm.Dest  = ctx.progressRb->GetGPUVirtualAddress() + (completed ? 4u : 0u);
    prm.Value = (dispatch.convOp << 16) | ((chunk + 1) & 0xFFFFu);
    D3D12_WRITEBUFFERIMMEDIATE_MODE m = completed ? D3D12_WRITEBUFFERIMMEDIATE_MODE_MARKER_OUT
                                                  : D3D12_WRITEBUFFERIMMEDIATE_MODE_MARKER_IN;
    l2->WriteBufferImmediate(1, &prm, &m);
}

void DescribeConverterAllocationsNear(uint64_t va) {
    std::unique_lock<std::mutex> lock(g_convMutex, std::try_to_lock);
    if (!lock.owns_lock()) {
        Log("[DRED]   wrapper buffers: converter busy, not listed");
        return;
    }
    struct Range { const char* what; int index; uint64_t lo, hi; };
    std::vector<Range> ranges;
    auto add = [&](const char* what, int index, ID3D12Resource* r) {
        if (r) {
            const uint64_t lo = r->GetGPUVirtualAddress();
            ranges.push_back({ what, index, lo, lo + r->GetDesc().Width });
        }
    };
    for (auto& kv : g_deviceContexts) {
        auto& ctx = kv.second;
        for (size_t i = 0; i < ctx.slots.size(); ++i) add("scratch slot", static_cast<int>(i), ctx.slots[i].buffer.Get());
        add("null-dst sink", -1, ctx.nullDstSink.Get());
        add("dump buffer", -1, ctx.dumpGpu.Get());
        add("dump readback", -1, ctx.dumpRb.Get());
        add("marker readback", -1, ctx.markerBuffer.Get());
        add("layout capture", -1, ctx.capGpu.Get());
        add("layout readback", -1, ctx.capRb.Get());
    }
    const Range* below = nullptr;
    const Range* above = nullptr;
    for (const auto& r : ranges) {
        if (va >= r.lo && va < r.hi) {
            Log("[DRED]   fault is INSIDE wrapper %s %d [0x%llx..0x%llx) at +0x%llx", r.what, r.index,
                static_cast<unsigned long long>(r.lo), static_cast<unsigned long long>(r.hi),
                static_cast<unsigned long long>(va - r.lo));
            return;
        }
        if (r.hi <= va && (!below || r.hi > below->hi)) below = &r;
        if (r.lo > va && (!above || r.lo < above->lo)) above = &r;
    }
    Log("[DRED]   wrapper buffers: %zu", ranges.size());
    if (below) {
        Log("[DRED]   nearest wrapper buffer below: %s %d [0x%llx..0x%llx), fault is 0x%llx past its end",
            below->what, below->index, static_cast<unsigned long long>(below->lo),
            static_cast<unsigned long long>(below->hi), static_cast<unsigned long long>(va - below->hi));
    }
    if (above) {
        Log("[DRED]   nearest wrapper buffer above: %s %d [0x%llx..0x%llx), 0x%llx after the fault",
            above->what, above->index, static_cast<unsigned long long>(above->lo),
            static_cast<unsigned long long>(above->hi), static_cast<unsigned long long>(above->lo - va));
    }
}

void FlushArgDumpsForDiagnostics() {
    std::unique_lock<std::mutex> lock(g_convMutex, std::try_to_lock);
    if (!lock.owns_lock()) {
        Log("[Dump] converter busy, pending argument dumps not printed");
        return;
    }
    for (auto& kv : g_deviceContexts) {
        FlushDumpsLocked(kv.second, true);
        AnalyseLayoutLocked(kv.second, true);
        WriteRealCapture(kv.second);
    }
}

bool PrepareGpuClusterArguments(
    ID3D12GraphicsCommandList* pCmdList,
    const NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_DESC& nvDesc,
    ConvertedGpuDispatch& outDispatch)
{
    outDispatch = {};
    outDispatch.indirectArgArrayAddr = nvDesc.indirectArgArray.StartAddress;
    outDispatch.indirectArgStride    = static_cast<uint32_t>(nvDesc.indirectArgArray.StrideInBytes);
    outDispatch.resultSizeArrayAddr  = nvDesc.resultSizeArray.StartAddress;
    outDispatch.resultSizeStride     = static_cast<uint32_t>(nvDesc.resultSizeArray.StrideInBytes);
    outDispatch.maxOperations        = nvDesc.inputs.maxArgCount;
    outDispatch.argCountAddr         = nvDesc.indirectArgCount;
    outDispatch.resultAddressArrayAddr = nvDesc.destinationAddressArray.StartAddress;
    outDispatch.resultAddressStride    = static_cast<uint32_t>(nvDesc.destinationAddressArray.StrideInBytes);

    if (!pCmdList || nvDesc.inputs.maxArgCount == 0) {
        return true;
    }

    ComPtr<ID3D12Device> pDevice;
    if (FAILED(pCmdList->GetDevice(IID_PPV_ARGS(&pDevice))) || !pDevice) {
        return false;
    }

    std::lock_guard<std::mutex> lock(g_convMutex);
    auto& ctx = g_deviceContexts[pDevice.Get()];
    if (!EnsureConverterPipeline(pDevice.Get(), ctx)) {
        return false;
    }
    const uint32_t nvType = static_cast<uint32_t>(nvDesc.inputs.type);
    const uint32_t splitK = nvType == kTypeBlasFromClas ? SplitBlasChunkSize() : SplitChunkSize();
    const bool split = splitK != 0 &&
        nvDesc.inputs.mode == NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_MODE_EXPLICIT_DESTINATIONS &&
        (nvType == NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_CLAS_FROM_TRIANGLES ||
         nvType == kTypeTemplates || nvType == kTypeInstantiate || nvType == kTypeBlasFromClas) &&
        nvDesc.inputs.maxArgCount > splitK && EnsureProgressBuffer(pDevice.Get(), ctx);
    ctx.convOpSeq = (ctx.convOpSeq + 1) & 0xFFFFu;
    if (ctx.convOpSeq == 0) ctx.convOpSeq = 1;
    ctx.currentConvOp = ctx.convOpSeq;
    ctx.currentSplitK = split ? splitK : 0;
    outDispatch.convOp = ctx.convOpSeq;

    if (DumpArgsEnabled()) {
        FlushDumpsLocked(ctx, false);
        AnalyseLayoutLocked(ctx, false);
        RecordArgDump(pCmdList, pDevice.Get(), ctx, nvDesc);
        RecordLayoutCapture(pCmdList, pDevice.Get(), ctx, nvDesc);
        if (nvType == kTypeBlasFromClas) RecordRealCapture(pCmdList, pDevice.Get(), ctx);
    }

    // Indirected addresses (pointer-to-pointer) cannot be followed by the converter CS.
    constexpr uint32_t kUnsupportedIndirection =
        NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_ADDRESS_RESOLUTION_FLAG_INDIRECTED_RESULT_SIZE_ARRAY |
        NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_ADDRESS_RESOLUTION_FLAG_INDIRECTED_INDIRECT_ARG_ARRAY |
        NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_ADDRESS_RESOLUTION_FLAG_INDIRECTED_INDIRECT_ARG_COUNT;
    if ((nvDesc.addressResolutionFlags & kUnsupportedIndirection) && !ctx.warnedAddressFlags) {
        Log("[Converter] WARNING: addressResolutionFlags=0x%x uses indirected arg/count/size arrays, "
            "which the argument converter treats as direct addresses", nvDesc.addressResolutionFlags);
        ctx.warnedAddressFlags = true;
    }

    uint32_t mode      = ~0u;
    uint32_t srcStride = static_cast<uint32_t>(nvDesc.indirectArgArray.StrideInBytes);
    uint32_t dstStride = srcStride;

    switch (nvDesc.inputs.type) {
    case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_CLAS_FROM_TRIANGLES:
        mode      = 0;
        srcStride = srcStride ? srcStride : 64u;
        dstStride = 80u;
        break;
    case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_CLUSTER_TEMPLATES_FROM_TRIANGLES:
        mode      = 1;
        srcStride = srcStride ? srcStride : 72u;
        dstStride = 96u;
        break;
    case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_INSTANTIATE_CLUSTER_TEMPLATES:
        mode      = 2;
        srcStride = srcStride ? srcStride : 32u;
        dstStride = 32u;
        break;
    case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_BUILD_BLAS_FROM_CLAS:
        mode      = 3;
        srcStride = srcStride ? srcStride : 16u;
        dstStride = 16u;
        break;
    case NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_TYPE_MOVE_CLUSTER_OBJECT:
    default:
        break; // identical layout: DXR reads the game's array directly
    }

    if (mode != ~0u && nvDesc.indirectArgArray.StartAddress != 0) {
        const uint64_t bytesNeeded = static_cast<uint64_t>(nvDesc.inputs.maxArgCount) * dstStride;
        const int slot = AcquireScratchSlot(pDevice.Get(), ctx, bytesNeeded);
        if (slot < 0) {
            return false;
        }
        ID3D12Resource* res = ctx.slots[slot].buffer.Get();
        uint64_t extra = 0;
        if (mode == 3 && BlasFakeClasEnabled()) extra = EnsureFakeClas(pCmdList, pDevice.Get(), ctx);
        if ((mode == 0 || mode == 1) && ForceGeom0Enabled()) extra |= 1;
        if (mode == 1 && TemplateNoHintEnabled()) extra |= 2;
        DispatchConversionCS(pCmdList, ctx,
            nvDesc.indirectArgArray.StartAddress, res->GetGPUVirtualAddress(), nvDesc.indirectArgCount,
            nvDesc.inputs.maxArgCount, srcStride, dstStride, mode, extra);
        // Converted args are consumed as indirect arguments by ExecuteIndirectRTASOperations.
        Transition(pCmdList, res, kScratchCanonicalState, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);

        outDispatch.argSlot              = slot;
        outDispatch.indirectArgArrayAddr = res->GetGPUVirtualAddress();
        outDispatch.indirectArgStride    = dstStride;
    }

    if (nvDesc.resultSizeArray.StartAddress != 0) {
        const uint64_t bytesNeeded = static_cast<uint64_t>(nvDesc.inputs.maxArgCount) * sizeof(uint64_t);
        const int slot = AcquireScratchSlot(pDevice.Get(), ctx, bytesNeeded);
        if (slot < 0) {
            // The conversion CS above is already recorded: let the marker cover the arg slot.
            if (outDispatch.argSlot >= 0) {
                Transition(pCmdList, ctx.slots[outDispatch.argSlot].buffer.Get(),
                           D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, kScratchCanonicalState);
                RecordSlotCompletion(pCmdList, ctx, &outDispatch.argSlot, 1);
            }
            return false;
        }
        outDispatch.sizeSlot             = slot;
        outDispatch.origResultSizeAddr   = nvDesc.resultSizeArray.StartAddress;
        outDispatch.origResultSizeStride = nvDesc.resultSizeArray.StrideInBytes
            ? static_cast<uint32_t>(nvDesc.resultSizeArray.StrideInBytes)
            : static_cast<uint32_t>(sizeof(uint32_t));
        outDispatch.resultSizeArrayAddr  = ctx.slots[slot].buffer->GetGPUVirtualAddress();
        outDispatch.resultSizeStride     = sizeof(uint64_t);
        outDispatch.needsResultDowncast  = true;
    }

    // Explicit destinations: redirect null addresses (unused slots) to a sink buffer.
    if (nvDesc.inputs.mode == NVAPI_D3D12_RAYTRACING_MULTI_INDIRECT_CLUSTER_OPERATION_MODE_EXPLICIT_DESTINATIONS &&
        nvDesc.destinationAddressArray.StartAddress != 0 && SanitizeDstEnabled() && EnsureNullDstSink(pDevice.Get(), ctx)) {
        const int slot = AcquireScratchSlot(pDevice.Get(), ctx, static_cast<uint64_t>(nvDesc.inputs.maxArgCount) * 8ull);
        if (slot >= 0) {
            ID3D12Resource* res = ctx.slots[slot].buffer.Get();
            const uint32_t srcStride = nvDesc.destinationAddressArray.StrideInBytes
                ? static_cast<uint32_t>(nvDesc.destinationAddressArray.StrideInBytes) : 8u;
            DispatchConversionCS(pCmdList, ctx, nvDesc.destinationAddressArray.StartAddress,
                res->GetGPUVirtualAddress(), nvDesc.indirectArgCount, nvDesc.inputs.maxArgCount,
                srcStride, 8u, 10, ctx.nullDstSink->GetGPUVirtualAddress());
            Transition(pCmdList, res, kScratchCanonicalState, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
            outDispatch.dstSlot                = slot;
            outDispatch.resultAddressArrayAddr = res->GetGPUVirtualAddress();
            outDispatch.resultAddressStride    = 8u;
        } else if (!ctx.warnedDstSanitize) {
            Log("[Converter] WARNING: no scratch for the destination array copy, null destinations not redirected");
            ctx.warnedDstSanitize = true;
        }
    }

    if (split) {
        const uint32_t chunks = (nvDesc.inputs.maxArgCount + splitK - 1) / splitK;
        bool ok = true;
        if (nvDesc.indirectArgCount) {
            // Per-chunk GPU counts derived from the game's count.
            const int slot = AcquireScratchSlot(pDevice.Get(), ctx, static_cast<uint64_t>(chunks) * 4ull);
            if (slot >= 0) {
                ID3D12Resource* res = ctx.slots[slot].buffer.Get();
                DispatchConversionCS(pCmdList, ctx, nvDesc.indirectArgCount, res->GetGPUVirtualAddress(),
                                     nvDesc.indirectArgCount, chunks, 4, 4, 12,
                                     (static_cast<uint64_t>(nvDesc.inputs.maxArgCount) << 32) | splitK);
                Transition(pCmdList, res, kScratchCanonicalState, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
                outDispatch.chunkSlot       = slot;
                outDispatch.chunkCountsAddr = res->GetGPUVirtualAddress();
            } else {
                ok = false;
            }
        }
        if (ok) {
            outDispatch.chunkSize = splitK;
            outDispatch.numChunks = chunks;
            if (!(ctx.splitLoggedTypes & (1u << (nvType & 31u)))) {
                ctx.splitLoggedTypes |= 1u << (nvType & 31u);
                Log("[Split] type=%u (op %u): %u chunks of %u arguments", nvType, outDispatch.convOp, chunks, splitK);
            }
        }
    }

    return true;
}

void FinalizeGpuClusterResultSizes(
    ID3D12GraphicsCommandList* pCmdList,
    const ConvertedGpuDispatch& dispatch)
{
    if (!pCmdList || (dispatch.argSlot < 0 && dispatch.sizeSlot < 0 && dispatch.dstSlot < 0 && dispatch.chunkSlot < 0)) {
        return;
    }

    ComPtr<ID3D12Device> pDevice;
    if (FAILED(pCmdList->GetDevice(IID_PPV_ARGS(&pDevice))) || !pDevice) {
        return;
    }

    std::lock_guard<std::mutex> lock(g_convMutex);
    auto it = g_deviceContexts.find(pDevice.Get());
    if (it == g_deviceContexts.end()) {
        return;
    }
    DeviceConverterContext& ctx = it->second;

    if (dispatch.argSlot >= 0) {
        Transition(pCmdList, ctx.slots[dispatch.argSlot].buffer.Get(),
                   D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, kScratchCanonicalState);
    }

    if (dispatch.sizeSlot >= 0) {
        ID3D12Resource* sizes = ctx.slots[dispatch.sizeSlot].buffer.Get();
        GlobalUavBarrier(pCmdList); // RTAS operation writes -> CS reads
        Transition(pCmdList, sizes, kScratchCanonicalState, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
        DispatchConversionCS(pCmdList, ctx,
            dispatch.resultSizeArrayAddr, dispatch.origResultSizeAddr, dispatch.argCountAddr,
            dispatch.maxOperations, dispatch.resultSizeStride, dispatch.origResultSizeStride,
            5 /* DowncastResultSizes */);
        GlobalUavBarrier(pCmdList); // game's resultSizeArray written by the CS
        Transition(pCmdList, sizes, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, kScratchCanonicalState);
    }

    if (dispatch.dstSlot >= 0) {
        Transition(pCmdList, ctx.slots[dispatch.dstSlot].buffer.Get(),
                   D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, kScratchCanonicalState);
    }

    if (dispatch.chunkSlot >= 0) {
        Transition(pCmdList, ctx.slots[dispatch.chunkSlot].buffer.Get(),
                   D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, kScratchCanonicalState);
    }

    const int slots[4] = { dispatch.argSlot, dispatch.sizeSlot, dispatch.dstSlot, dispatch.chunkSlot };
    RecordSlotCompletion(pCmdList, ctx, slots, 4);
}

void ShutdownGpuConverter(bool processTerminating) {
    std::lock_guard<std::mutex> lock(g_convMutex);
    for (auto& kv : g_deviceContexts) {
        FlushDumpsLocked(kv.second, false);
        AnalyseLayoutLocked(kv.second, false);
        WriteRealCapture(kv.second);
    }
    if (processTerminating) {
        // D3D12Core.dll / the driver are already unloaded when the process exits (they detach
        // before us): releasing the PSO, root signature and buffers would call into unmapped
        // code (0xC0000409 at exit). Leak them; the OS reclaims everything.
        new std::unordered_map<ID3D12Device*, DeviceConverterContext>(std::move(g_deviceContexts));
    }
    g_deviceContexts.clear();
}

ID3D12Resource* GetConverterScratchForTest(ID3D12Device* pDevice, int slot) {
    std::lock_guard<std::mutex> lock(g_convMutex);
    auto it = g_deviceContexts.find(pDevice);
    if (it == g_deviceContexts.end() || slot < 0 || slot >= static_cast<int>(it->second.slots.size())) {
        return nullptr;
    }
    return it->second.slots[slot].buffer.Get();
}

